            <tr>
              <th>Product</th>
              <th>Owner</th>
              <th>Type</th>
              <th>Status</th>
              <th>Price</th>
              <th>Updated</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {productsPage?.content.map((product) => (
              <tr key={product.id}>
