import React, { useMemo, useState } from 'react';
import { JSONContent } from '@tiptap/react';
import {
  HiArrowDown,
  HiArrowUp,
  HiOutlinePencil,
  HiOutlineTrash,
} from 'react-icons/hi';

import QuizWizard from '../../quiz-wizard/quiz-wizard.component';
import {
  Button,
  Drawer,
  Icon,
  Radio,
  RadioGroup,
  RichTextEditor,
  StatusBadge,
  Textarea,
  UppyFileUploader,
} from '@shared/ui';
import { AppDispatch, CourseLesson, LessonType } from 'core/api/models';
import { deleteCourseLesson } from 'core/store/product-store';
import { useDispatch, useSelector } from 'react-redux';
import { selectAuthUser } from 'core/store/auth-store';
import { EditableTitle } from '../editable-title';
import { LESSON_META } from 'core/constants';
import { useLessonAutosave } from 'domains/app/features/product-form/hooks';
import { getCssVar } from '@shared/utils';

import './lesson-editor.styles.scss';

interface LessonEditorProps {
  lesson: CourseLesson;
  index: number;
  productId: string;
  sectionId: string;
  // eslint-disable-next-line no-unused-vars
  removeLessonFromList: (index: number) => void;
  // eslint-disable-next-line no-unused-vars
  onChange: (index: number, lesson: CourseLesson) => void;
  onMoveUp?: () => void;
  onMoveDown?: () => void;
  canMoveUp?: boolean;
  canMoveDown?: boolean;
}

const editableLessonTypes: Array<{
  type: LessonType;
  label: string;
  description: string;
}> = [
  {
    type: 'VIDEO',
    label: 'Video',
    description: 'Use for lessons centered on a video asset.',
  },
  {
    type: 'ARTICLE',
    label: 'Article',
    description: 'Use for written lessons with rich text content.',
  },
  {
    type: 'QUIZ',
    label: 'Quiz',
    description: 'Use for MVP single-choice, multi-choice, and true/false checks.',
  },
];

const getTypeLabel = (type?: LessonType) => {
  switch (type) {
    case 'VIDEO':
      return 'Video';
    case 'ARTICLE':
      return 'Article';
    case 'QUIZ':
      return 'Quiz';
    default:
      return 'Lesson';
  }
};

const parseArticleContent = (content?: string): JSONContent | undefined => {
  if (!content) {
    return undefined;
  }

  try {
    return JSON.parse(content) as JSONContent;
  } catch {
    return {
      type: 'doc',
      content: [
        {
          type: 'paragraph',
          content: [{ type: 'text', text: content }],
        },
      ],
    };
  }
};

const LessonEditor: React.FC<LessonEditorProps> = ({
  lesson,
  index,
  productId,
  sectionId,
  removeLessonFromList,
  onChange,
  onMoveUp = () => undefined,
  onMoveDown = () => undefined,
  canMoveUp = false,
  canMoveDown = false,
}) => {
  const dispatch = useDispatch<AppDispatch>();
  const user = useSelector(selectAuthUser);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [videoFileName, setVideoFileName] = useState<string | null>(null);
  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
  const [operationError, setOperationError] = useState<string | null>(null);
  const videoBackendPendingMessage =
    'Course video asset persistence is backend-pending; this records the ' +
    'intended video lesson state without pretending the file is uploaded.';

  const { isAutosaving, lastSavedAt } = useLessonAutosave({
    lesson,
    productId,
    user,
    sectionId,
    dispatch,
  });

  const articleInitialContent = useMemo(
    () => parseArticleContent(lesson.content),
    [lesson.id],
  );

  const updateLesson = (patch: Partial<CourseLesson>) => {
    const next: CourseLesson = {
      ...lesson,
      ...patch,
      productId,
      sectionId,
    };
    onChange(index, next);
  };

  const handleDeleteLesson = () => {
    if (!lesson.id) {
      removeLessonFromList(index);
      return;
    }

    dispatch(
      deleteCourseLesson({
        productId,
        sectionId,
        lessonId: lesson.id,
      }),
    )
      .unwrap()
      .then(() => {
        removeLessonFromList(index);
      })
      .catch((error) => {
        setOperationError(
          typeof error === 'string'
            ? error
            : 'Could not delete this lesson. Try again.',
        );
      });
  };

  const onVideoUploadChange = (files: File[]) => {
    const file = files[0] ?? null;
    setVideoFileName(file?.name ?? null);
    if (file) {
      updateLesson({
        videoUrl: `pending-video-asset://${encodeURIComponent(file.name)}`,
      });
    }
  };

  const handleArticleChange = (json: JSONContent) => {
    updateLesson({ content: JSON.stringify(json) });
  };

  const renderContentField = () => {
    switch (lesson.type) {
      case 'VIDEO':
        return (
          <div className="lesson-drawer__backend-note">
            <UppyFileUploader
              onFilesChange={onVideoUploadChange}
              allowedFileTypes={['video/*']}
            />
            <p>
              {videoFileName
                ? `${videoFileName} is selected for this lesson. Durable Course video upload remains backend-pending.`
                : videoBackendPendingMessage}
            </p>
          </div>
        );

      case 'ARTICLE':
        return (
          <div className="form-input-group">
            <RichTextEditor
              initialContent={articleInitialContent}
              onChange={handleArticleChange}
            />
          </div>
        );

      case 'QUIZ':
        return <QuizWizard lesson={lesson} updateLesson={updateLesson} />;

      default:
        return (
          <p className="lesson-drawer__backend-note">
            Choose Video, Article, or Quiz for this MVP Course lesson.
          </p>
        );
    }
  };

  const lessonType = lesson.type ?? 'VIDEO';
  const typeLabel = getTypeLabel(lesson.type);
  const meta = LESSON_META[lessonType];
  const lessonTitle = lesson.title || `Untitled lesson ${index + 1}`;

  return (
    <div className="lesson-editor" id={`lesson-${lesson.id ?? index}`}>
      <div className="lesson-row">
        <span className="lesson-row__type">
          <Icon icon={meta.icon} color={meta.color} size={18} />
          <span>{typeLabel}</span>
        </span>
        <div className="lesson-row__title">
          <strong>{lessonTitle}</strong>
          {lesson.description && <span>{lesson.description}</span>}
        </div>
        <StatusBadge
          label={isAutosaving ? 'Saving' : lastSavedAt ? 'Saved' : 'Draft'}
          tone={isAutosaving ? 'info' : 'neutral'}
          size="sm"
        />
        <div className="lesson-row__actions">
          <Button
            type="button"
            variant="tertiary"
            size="sm"
            onClick={onMoveUp}
            disabled={!canMoveUp}
            aria-label={`Move ${lessonTitle} up`}
          >
            <Icon icon={HiArrowUp} size={16} color={getCssVar('--text-primary')} />
            <span>Up</span>
          </Button>
          <Button
            type="button"
            variant="tertiary"
            size="sm"
            onClick={onMoveDown}
            disabled={!canMoveDown}
            aria-label={`Move ${lessonTitle} down`}
          >
            <Icon
              icon={HiArrowDown}
              size={16}
              color={getCssVar('--text-primary')}
            />
            <span>Down</span>
          </Button>
          <Button
            type="button"
            variant="secondary"
            size="sm"
            onClick={() => setIsDrawerOpen(true)}
            aria-label={`Edit ${lessonTitle}`}
          >
            <Icon
              icon={HiOutlinePencil}
              size={16}
              color={getCssVar('--text-primary')}
            />
            <span>Edit</span>
          </Button>
          <Button
            type="button"
            variant="danger"
            size="sm"
            onClick={() => setIsConfirmingDelete(true)}
            aria-label={`Delete ${lessonTitle}`}
          >
            <Icon
              icon={HiOutlineTrash}
              size={16}
              color={getCssVar('--text-primary')}
            />
            <span>Delete</span>
          </Button>
        </div>
      </div>

      {operationError && (
        <p className="lesson-row__error" role="alert">
          {operationError}
        </p>
      )}

      {isConfirmingDelete && (
        <div className="lesson-row__confirm" role="alertdialog">
          <div>
            <strong>Delete {lessonTitle}?</strong>
            <p>This removes the lesson from this Course section.</p>
          </div>
          <div>
            <Button
              type="button"
              variant="tertiary"
              onClick={() => setIsConfirmingDelete(false)}
            >
              Cancel
            </Button>
            <Button type="button" variant="danger" onClick={handleDeleteLesson}>
              Delete lesson
            </Button>
          </div>
        </div>
      )}

      <Drawer
        open={isDrawerOpen}
        title={
          <div className="lesson-drawer__title">
            <span>{typeLabel}</span>
            <strong>{lessonTitle}</strong>
          </div>
        }
        onClose={() => setIsDrawerOpen(false)}
        closeLabel={`Close ${lessonTitle} editor`}
        className="lesson-editor-drawer"
      >
        <div className="lesson-drawer">
          <EditableTitle
            value={lesson.title ?? ''}
            placeholder={`Untitled lesson ${index + 1}`}
            onChange={(title: string) => updateLesson({ title })}
          />

          <RadioGroup
            name={`edit-lesson-type-${lesson.id ?? index}`}
            label="Lesson type"
            value={lessonType}
            onChange={(type) => updateLesson({ type: type as LessonType })}
            className="lesson-drawer__types"
          >
            {editableLessonTypes.map((option) => (
              <Radio
                key={option.type}
                value={option.type}
                label={option.label}
                description={option.description}
              />
            ))}
          </RadioGroup>

          <Textarea
            label="Lesson description"
            name={`lesson-description-${lesson.id ?? index}`}
            value={lesson.description ?? ''}
            onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) =>
              updateLesson({ description: e.target.value })
            }
            placeholder="Write a short description for this lesson."
            block
          />

          <section className="lesson-drawer__content">
            <h3>{typeLabel} content</h3>
            {renderContentField()}
          </section>
        </div>
      </Drawer>
    </div>
  );
};

export default LessonEditor;

import React, { useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate, useParams } from 'react-router-dom';
import DOMPurify from 'dompurify';
import { toast } from 'sonner';

import {
  AppDispatch,
  hasRole,
  ProductMinimised,
  RootState,
  UserRole,
} from 'core/api/models';
import {
  enrollInFreeProductAPI,
  getProductAccessAPI,
  getProductFileDownloadAPI,
} from 'core/api/services';
import { selectAuthUser } from 'core/store/auth-store';
import {
  clearCurrentProduct,
  getProductById,
  selectCurrentProduct,
  selectProductsError,
  selectProductsLoading,
} from 'core/store/product-store';
import {
  fetchPublicProductLandingPageConfig,
  selectPublicProductLandingPageConfigByProductId,
} from 'core/store/product-landing-page-store';
import {
  fetchPublicStorefront,
  selectCreatorStorefrontConfig,
  selectPublicStorefrontByCreatorId,
} from 'core/store/storefront-store';
import { addProductToCart, selectCartIds } from 'core/store/shop-cart';
import { Button, LegacyExpansionPanel } from '@shared/ui';
import {
  getProductLandingPageViewModel,
  isPublicProductLandingPageProduct,
  ProductLandingPage,
} from 'domains/app/features/product-landing-page';
import { appRoutes } from '../../routes/routes';

import './product-page.styles.scss';

const ProductPage: React.FC = () => {
  const { type, id } = useParams();
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const user = useSelector(selectAuthUser);
  const cartIds = useSelector(selectCartIds);
  const currentProduct = useSelector(selectCurrentProduct);
  const loading = useSelector(selectProductsLoading);
  const error = useSelector(selectProductsError);
  const creatorStorefrontConfig = useSelector(selectCreatorStorefrontConfig);
  const [hasAccess, setHasAccess] = useState(false);
  const [enrolling, setEnrolling] = useState(false);
  const loadedProduct =
    currentProduct?.id && currentProduct.id === id ? currentProduct : null;
  const publicStorefront = useSelector((state: RootState) =>
    selectPublicStorefrontByCreatorId(state, loadedProduct?.userId),
  );
  const landingPageConfig = useSelector((state: RootState) =>
    selectPublicProductLandingPageConfigByProductId(state, loadedProduct?.id),
  );
  const isOwner =
    Boolean(user?.id && user.id === loadedProduct?.userId) ||
    hasRole(user?.roles, UserRole.ADMIN);

  useEffect(() => {
    if (id) {
      dispatch(clearCurrentProduct());
      dispatch(getProductById({ productId: id }));
    }
  }, [dispatch, id]);

  useEffect(() => {
    if (loadedProduct && type && loadedProduct.type !== type) {
      navigate(appRoutes.product(loadedProduct.id), { replace: true });
    }
  }, [loadedProduct, navigate, type]);

  useEffect(() => {
    if (!user || !id) {
      setHasAccess(false);
      return;
    }

    getProductAccessAPI(id)
      .then((access) => setHasAccess(access.hasAccess))
      .catch(() => setHasAccess(false));
  }, [id, user]);

  useEffect(() => {
    if (
      loadedProduct?.userId &&
      isPublicProductLandingPageProduct(loadedProduct) &&
      !publicStorefront
    ) {
      dispatch(fetchPublicStorefront(loadedProduct.userId));
    }
  }, [dispatch, loadedProduct, publicStorefront]);

  useEffect(() => {
    if (loadedProduct && isPublicProductLandingPageProduct(loadedProduct)) {
      dispatch(fetchPublicProductLandingPageConfig(loadedProduct.id));
    }
  }, [dispatch, loadedProduct]);

  const viewModel = useMemo(() => {
    if (!loadedProduct || !isPublicProductLandingPageProduct(loadedProduct)) {
      return null;
    }

    return getProductLandingPageViewModel({
      product: loadedProduct,
      currentUser: user,
      publicStorefront,
      creatorStorefrontTheme: isOwner
        ? creatorStorefrontConfig?.theme
        : undefined,
      landingPageConfig,
    });
  }, [
    creatorStorefrontConfig?.theme,
    isOwner,
    landingPageConfig,
    loadedProduct,
    publicStorefront,
    user,
  ]);

  const numericPrice =
    loadedProduct?.price === 'free' ? 0 : Number(loadedProduct?.price ?? 0);
  const isFree = numericPrice === 0;
  const isMembershipProduct = loadedProduct?.type === 'MEMBERSHIP';
  const isInCart = Boolean(loadedProduct?.id && cartIds.has(loadedProduct.id));

  const toSummary = (): ProductMinimised | null => {
    if (!loadedProduct) {
      return null;
    }
    return {
      id: loadedProduct.id,
      title: loadedProduct.name,
      description: loadedProduct.description,
      type: loadedProduct.type,
      price: loadedProduct.price,
      status: loadedProduct.status,
      imageUrl: loadedProduct.imageUrl,
      createdById: loadedProduct.userId,
      createdAt: loadedProduct.createdAt,
      updatedAt: loadedProduct.updatedAt,
    };
  };

  const handleEnroll = async () => {
    if (!user) {
      navigate('/auth/login');
      return;
    }
    if (!loadedProduct) {
      return;
    }

    setEnrolling(true);
    try {
      await enrollInFreeProductAPI(loadedProduct.id);
      setHasAccess(true);
      await dispatch(getProductById({ productId: loadedProduct.id })).unwrap();
      toast.success('Added to your library');
    } catch {
      toast.error('This product could not be added to your library.');
    } finally {
      setEnrolling(false);
    }
  };

  const handleAddToCart = () => {
    const product = toSummary();
    if (product && !isInCart) {
      dispatch(addProductToCart(product));
    }
  };

  const handleDownload = async (fileId?: string) => {
    if (!loadedProduct || !fileId) {
      return;
    }
    try {
      const { url } = await getProductFileDownloadAPI(
        loadedProduct.id,
        fileId,
      );
      window.location.assign(url);
    } catch {
      toast.error('The download could not be started.');
    }
  };

  if (loading && !loadedProduct) {
    return (
      <main className="product-page-state" aria-busy="true">
        <h1>Loading Product</h1>
        <p>Preparing this Product page.</p>
      </main>
    );
  }

  if (error || !loadedProduct) {
    return (
      <main className="product-page-state" role="alert">
        <h1>Product unavailable</h1>
        <p>{error ?? 'This Product page could not be loaded.'}</p>
      </main>
    );
  }

  if (!viewModel) {
    return (
      <main className="product-page-state" role="alert">
        <h1>Product unavailable</h1>
        <p>This Product is not publicly available.</p>
      </main>
    );
  }

  const commerceActions = isOwner ? (
    <Button
      type="button"
      variant="primary"
      onClick={() => navigate(appRoutes.productsEdit(loadedProduct.id))}
    >
      Edit product
    </Button>
  ) : hasAccess ? (
    <Button type="button" variant="primary" disabled>
      In your library
    </Button>
  ) : isFree ? (
    <Button
      type="button"
      variant="primary"
      disabled={enrolling}
      onClick={handleEnroll}
    >
      {enrolling ? 'Adding...' : 'Enroll for free'}
    </Button>
  ) : isMembershipProduct ? (
    <Button type="button" variant="primary" disabled>
      Membership checkout unavailable
    </Button>
  ) : (
    <div className="product-page__commerce-actions">
      <Button
        type="button"
        variant="primary"
        disabled={isInCart}
        onClick={handleAddToCart}
      >
        {isInCart ? 'Already in cart' : 'Add to cart'}
      </Button>
      <Button
        type="button"
        variant="secondary"
        onClick={() => {
          handleAddToCart();
          navigate(appRoutes.cart);
        }}
      >
        Buy now
      </Button>
    </div>
  );

  return (
    <>
      <ProductLandingPage product={viewModel} commerceActions={commerceActions} />
      {(hasAccess || isOwner) && loadedProduct.type === 'COURSE' && (
        <section className="product-page__protected-content">
          <h2>Course content</h2>
          {loadedProduct.sections?.map((section) => (
            <LegacyExpansionPanel key={section.id} header={section.title || ''}>
              {section.description && <p>{section.description}</p>}
              {section.lessons?.map((lesson) => (
                <article key={lesson.id} className="product-page__lesson">
                  <h3>{lesson.title}</h3>
                  {lesson.content && (
                    <div
                      dangerouslySetInnerHTML={{
                        __html: DOMPurify.sanitize(lesson.content),
                      }}
                    />
                  )}
                  {lesson.videoUrl && (
                    <video controls src={lesson.videoUrl}>
                      <track kind="captions" />
                    </video>
                  )}
                </article>
              ))}
            </LegacyExpansionPanel>
          ))}
        </section>
      )}
      {(hasAccess || isOwner) && loadedProduct.type === 'DOWNLOAD' && (
        <section className="product-page__protected-content">
          <h2>Downloads</h2>
          {loadedProduct.sections?.map((section) => (
            <LegacyExpansionPanel key={section.id} header={section.title || ''}>
              {section.files?.map((file) => (
                <button
                  key={file.id}
                  type="button"
                  className="product-page__download"
                  onClick={() => handleDownload(file.id)}
                >
                  {file.fileName}
                </button>
              ))}
            </LegacyExpansionPanel>
          ))}
        </section>
      )}
    </>
  );
};

export default ProductPage;

import React from 'react';
import { useEditor, EditorContent, JSONContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Image from '@tiptap/extension-image';
import Link from '@tiptap/extension-link';
import TaskList from '@tiptap/extension-task-list';
import TaskItem from '@tiptap/extension-task-item';
import Underline from '@tiptap/extension-underline';

import RTEMenuBar from './rte-menu-bar/rte-menu-bar.component';

import './rich-text-editor.styles.scss';

interface RichTextEditorProps {
  initialContent?: JSONContent;
  // eslint-disable-next-line no-unused-vars
  onChange?: (content: JSONContent) => void;
}

const RichTextEditor: React.FC<RichTextEditorProps> = ({
  initialContent,
  onChange,
}) => {
  // 1) Initialize the editor instance via useEditor()
  const editor = useEditor({
    extensions: [
      StarterKit,
      Link.configure({
        openOnClick: true,
        autolink: true,
        linkOnPaste: true,
      }),
      TaskList,
      TaskItem.configure({
        nested: true,
      }),
      Image,
      Underline,
    ],
    content: initialContent || '<p>Start writing your lesson…</p>',
    onUpdate: ({ editor }) => {
      // TipTap’s JSON document model; call onChange if provided
      const json = editor.getJSON();
      onChange?.(json);
    },
  });

  // 2) Clean up on unmount (optional)
  React.useEffect(
    () => () => {
      editor?.destroy();
    },
    [editor],
  );

  return (
    <div className="course-editor-container">
      <RTEMenuBar editor={editor} />
      {/* EditorContent is the actual editable area. */}
      <EditorContent editor={editor} className="rte-content" />
    </div>
  );
};

export default RichTextEditor;

import React, { useEffect, useMemo, useRef, useState } from 'react';

import { Button, Input, Radio, RadioGroup } from '@shared/ui';
import { CourseLesson, QuizDraft, QuizQuestion } from 'core/api/models';
import QuestionCard from './question-card/question-card.component';

import './quiz-wizard.styles.scss';
import {
  autoSplitQuizPoints,
  getEmptyMCQ,
  normalizeQuestionPositions,
  syncTotalScoreToPoints,
} from '../utils/quiz.utils';

interface QuizWizardProps {
  lesson?: Partial<CourseLesson>;
  // eslint-disable-next-line no-unused-vars
  updateLesson: (quiz: Partial<CourseLesson>) => void; // hook for API integration
}

const QuizWizard: React.FC<QuizWizardProps> = ({ lesson, updateLesson }) => {
  const didInit = useRef(false);

  useEffect(() => {
    if (didInit.current) {
      return;
    }
    didInit.current = true;

    const nextQuiz = ensureQuizDefaults(lesson);
    // Only write if lesson.quiz is missing or incomplete
    const shouldWrite =
      !lesson?.quiz ||
      !lesson.quiz.questions?.length ||
      lesson.quiz.passingScore === null ||
      lesson.quiz.totalScore === null;

    if (shouldWrite) {
      updateLesson({ quiz: nextQuiz });
    }
  }, []);

  const [scoreType, setScoreType] = useState<'auto' | 'manual'>('auto');

  const totalPoints = useMemo(
    () => lesson?.quiz?.questions?.reduce((sum, q) => sum + q.points, 0),
    [lesson?.quiz?.questions],
  );

  const ensureQuizDefaults = (lesson?: Partial<CourseLesson>): QuizDraft => {
    const existing = lesson?.quiz;

    return {
      passingScore: existing?.passingScore ?? 80,
      totalScore: existing?.totalScore ?? 100,
      questions: existing?.questions?.length
        ? existing.questions
        : [getEmptyMCQ(1)],
    };
  };

  useEffect(() => {
    if (scoreType !== 'auto') {
      return;
    }

    const current = lesson?.quiz;
    if (!current?.questions?.length) {
      return;
    }

    const nextQuiz = autoSplitQuizPoints(current);

    // Important: only update if something changed (function returns same object if no change)
    if (nextQuiz !== current) {
      updateLesson({ quiz: nextQuiz });
    }
  }, [scoreType, lesson?.quiz, updateLesson]);

  // Manual mode: keep totalScore in sync with sum of question points
  useEffect(() => {
    if (scoreType !== 'manual') {
      return;
    }

    const current = lesson?.quiz;
    if (!current?.questions?.length) {
      return;
    }

    const nextQuiz = syncTotalScoreToPoints(current);

    if (nextQuiz !== current) {
      updateLesson({ quiz: nextQuiz });
    }
  }, [scoreType, lesson?.quiz, updateLesson]);

  const updateQuestion = (qid: string, next: QuizQuestion) => {
    const current = lesson?.quiz ?? ensureQuizDefaults(lesson);
    const nextQuestions = current.questions?.map((q) =>
      q.id === qid ? next : q,
    );

    // keep positions in sync if you want:
    // const normalized = nextQuestions.map((q, i) => ({ ...q, position: i + 1 }));

    updateLesson({ quiz: { ...current, questions: nextQuestions } });
  };

  const removeQuestion = (qid: string) => {
    const current = lesson?.quiz ?? ensureQuizDefaults(lesson);

    updateLesson({
      quiz: {
        ...current,
        questions: current.questions?.filter((q) => q.id !== qid),
      },
    });
  };

  const moveQuestion = (qid: string, dir: -1 | 1) => {
    const current = lesson?.quiz ?? ensureQuizDefaults(lesson);
    const questions = current.questions ?? [];

    const idx = questions.findIndex((q) => q.id === qid);
    if (idx < 0) {
      return;
    }

    const next = [...questions];
    const newIdx = Math.min(next.length - 1, Math.max(0, idx + dir));
    if (newIdx === idx) {
      return;
    }

    const [spliced] = next.splice(idx, 1);
    next.splice(newIdx, 0, spliced);

    updateLesson({
      quiz: {
        ...current,
        questions: normalizeQuestionPositions(next),
      },
    });
  };

  const addQuestion = () => {
    const current = lesson?.quiz ?? ensureQuizDefaults(lesson);
    const questions = current.questions ?? [];

    const next = [...questions, getEmptyMCQ(questions.length + 1)];

    updateLesson({
      quiz: {
        ...current,
        questions: normalizeQuestionPositions(next),
      },
    });
  };

  const updateQuiz = (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>,
  ) => {
    const { name, value } = e.target;
    const quiz = { ...lesson?.quiz, [name]: value };
    updateLesson({ quiz });
  };

  return (
    <div className="quiz-wizard">
      <RadioGroup
        name="scoreType"
        value={scoreType}
        onChange={(v) => setScoreType(v as 'auto' | 'manual')}
        label="Points distribution"
        className="score-radios"
      >
        <Radio
          value="auto"
          label="Auto-Split"
          description="Distribute the total points evenly across all questions."
        />
        <Radio
          value="manual"
          label="Manual Split"
          description="Set points on each question individually."
        />
      </RadioGroup>

      <div className="scores-row">
        <Input
          value={lesson?.quiz?.passingScore ?? 80}
          label="Passing Score"
          name="passingScore"
          type="number"
          className="score-input"
          onChange={updateQuiz}
        />
        <Input
          value={
            scoreType === 'auto'
              ? (lesson?.quiz?.totalScore ?? 0)
              : (totalPoints ?? 100)
          }
          label="Total points"
          name="totalPoints"
          className="score-input"
          type="number"
          readOnly={scoreType === 'manual'}
          onChange={updateQuiz}
        />
      </div>

      <section className="questions">
        {lesson?.quiz?.questions?.map((q, idx) => (
          <QuestionCard
            key={idx}
            question={q}
            index={idx}
            readOnly={scoreType === 'auto'}
            // onTypeChange={(type) => onTypeChange(q, type)}
            onChange={(next) => updateQuestion(q.id, next)}
            onRemove={() => removeQuestion(q.id)}
            onMove={(dir) => moveQuestion(q.id, dir)}
          />
        ))}
      </section>

      <section>
        <Button type="button" variant="primary" onClick={() => addQuestion()}>
          Add question
        </Button>
      </section>
    </div>
  );
};

export default QuizWizard;

