  }

  .storefront-builder__customize {
    right: 16px;
    bottom: 16px;
  }

  .storefront-builder__customize-drawer {
    display: grid;
    height: min(78vh, 680px);
    align-self: end;
    border-top-left-radius: $radius-lg;
    border-top-right-radius: $radius-lg;
  }
}

