import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';

import { fetchProducts, SearchResponse } from 'core/api/services';
import { ProductBox } from 'domains/app/components';
import { ProductMinimised } from 'core/api/models';

import './search-page.styles.scss';

const SearchResultsPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const term = searchParams.get('term') ?? '';
  const pageParam = parseInt(searchParams.get('page') || '0', 10);
  const [page, setPage] = useState<number>(pageParam);
  const size = 20;

  // Fetch page of results
  const { data, isLoading, isError } = useQuery<
    SearchResponse<ProductMinimised>,
    Error
  >({
    queryKey: ['products-search', term, page],
    queryFn: () => fetchProducts({ term, page, size }),
  });

  // Sync page state to URL
  useEffect(() => {
    const params = new URLSearchParams({ term });
    if (page > 0) {
      params.set('page', String(page));
    }
    navigate({ search: params.toString() }, { replace: true });
  }, [term, page, navigate]);

  // Prefetch next page for smoother transitions
  useEffect(() => {
    if (
      data &&
      data.pageable &&
      data?.pageable?.pageNumber < data.totalPages - 1
    ) {
      fetchProducts({ term, page: page + 1, size });
    }
  }, [data, term, page]);

  if (isLoading) {
    return <div className="results-loading">Loading results...</div>;
  }
  if (isError) {
    return (
      <div className="results-error">Couldn&apos;t load results—try again.</div>
    );
  }

  return (
    <div className="search-page">
      <div className="results-container">
        <h1 className="results-title">Results for “{term}”</h1>

        {data?.content.length === 0 ? (
          <p className="results-empty">No products found for “{term}”.</p>
        ) : (
          <ul className="results-list">
            {data?.content.map((p: ProductMinimised) => (
              <ProductBox key={p.id} product={p} />
            ))}
          </ul>
        )}

        <div className="results-pagination">
          <button
            onClick={() => setPage((prev) => Math.max(prev - 1, 0))}
            disabled={page === 0}
            className="pagination-button"
          >
            Prev
          </button>
          <span className="pagination-info">
            Page {data && data.number && data.number + 1} of{' '}
            {data && data.totalPages}
          </span>
          {data && (
            <button
              onClick={() => setPage((prev) => prev + 1)}
              disabled={data.number + 1 >= data.totalPages}
              className="pagination-button"
            >
              Next
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default SearchResultsPage;

package com.myproject.video.video_platform.repository.products;

import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.user.User;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.JpaSpecificationExecutor;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.UUID;

@Repository
public interface ProductRepository extends JpaRepository<Product, UUID>, JpaSpecificationExecutor<Product> {
    List<Product> findAllByUser(User user);

    /**
     * EXPLORE: search across all products by product.name OR user.firstName OR user.lastName
     */
    @Query("""
    SELECT p
      FROM Product p
      JOIN p.user u
     WHERE lower(p.name)       LIKE %:term%
        OR lower(u.firstName)  LIKE %:term%
        OR lower(u.lastName)   LIKE %:term%
    """)
    Page<Product> searchByNameOrOwner(
            @Param("term") String term,
            Pageable pageable
    );

    /**
     * LIBRARY / TEACHER page: search this user’s products by product.name only
     */
    @Query("""
    SELECT p
      FROM Product p
     WHERE p.user.id = :userId
       AND lower(p.name) LIKE %:term%
    """)
    Page<Product> searchByUserAndName(
            @Param("userId") UUID userId,
            @Param("term")   String term,
            Pageable pageable
    );
}

package com.myproject.video.video_platform.controller.product;

import com.myproject.video.video_platform.controller.docs.product.ProductsApiDoc;
import com.myproject.video.video_platform.dto.products.AbstractProductRequestDto;
import com.myproject.video.video_platform.dto.products.AbstractProductResponseDto;
import com.myproject.video.video_platform.dto.products.ProductMinimised;
import com.myproject.video.video_platform.service.product.ProductService;
import com.myproject.video.video_platform.service.entitlement.ProductContentAccessService;
import io.swagger.v3.oas.annotations.tags.Tag;
import lombok.extern.slf4j.Slf4j;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.domain.Sort;
import org.springframework.data.web.PageableDefault;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

@Slf4j
@RestController
@RequestMapping("/api/products")
@Tag(name = "Products", description = "Create and manage course, download, consultation, and Membership products.")
public class ProductsController implements ProductsApiDoc {

    private final ProductService productService;
    private final ProductContentAccessService contentAccessService;

    public ProductsController(
            ProductService productService,
            ProductContentAccessService contentAccessService
    ) {
        this.productService = productService;
        this.contentAccessService = contentAccessService;
    }

    @PostMapping
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    @Override
    public ResponseEntity<AbstractProductResponseDto> createProduct(@RequestBody AbstractProductRequestDto request) {
        log.info("Received create product request: {}", request);
        AbstractProductResponseDto response = productService.createProduct(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }

    @GetMapping(params = "userId")
    @Override
    public ResponseEntity<List<AbstractProductResponseDto>> getProducts(@RequestParam(name = "userId") String userId) {
        List<AbstractProductResponseDto> response = contentAccessService.protectProductResponses(
                productService.getAllProductsForUser(userId)
        );
        return ResponseEntity.status(HttpStatus.OK).body(response);
    }

    @GetMapping(params = "ownerId")
    public ResponseEntity<List<ProductMinimised>> getProductsSummary(
            @RequestParam(name = "ownerId") String ownerId
    ) {
        List<ProductMinimised> response = productService.getProductSummariesForOwner(ownerId);
        return ResponseEntity.ok(response);
    }

    @GetMapping("/get-all-products-min")
    @Override
    public ResponseEntity<List<ProductMinimised>> getAllProductsMin(
            @RequestParam(name = "userId", required = false) String userId
    ) {
        List<ProductMinimised> response;
        if (userId != null) {
            response = productService.getAllProductsMinimisedForUser(userId);
        } else {
            response = productService.getAllProductsMinimised();
        }
        return ResponseEntity.ok(response);
    }

    @GetMapping(value = "/getProduct")
    @Override
    public ResponseEntity<AbstractProductResponseDto> getProductById(
            @RequestParam(name = "productId") String productId,
            @RequestParam(name = "type") String type) {

        AbstractProductResponseDto response = contentAccessService.protectProductResponse(
                productService.getProductByIdAndType(productId, type)
        );
        return ResponseEntity.status(HttpStatus.OK).body(response);
    }

    @GetMapping("/{productId}")
    public ResponseEntity<AbstractProductResponseDto> getProductById(
            @PathVariable("productId") String productId
    ) {
        AbstractProductResponseDto response = contentAccessService.protectProductResponse(
                productService.getProductById(productId)
        );
        return ResponseEntity.ok(response);
    }

    @PutMapping
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    @Override
    public ResponseEntity<AbstractProductResponseDto> updateProduct(@RequestBody AbstractProductRequestDto request) {
        log.info("Received update product request: {}", request.toString());
        AbstractProductResponseDto response = productService.updateProduct(request);
        return ResponseEntity.status(HttpStatus.ACCEPTED).body(response);
    }

    @PatchMapping("/{productId}")
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    public ResponseEntity<AbstractProductResponseDto> patchProduct(
            @PathVariable("productId") String productId,
            @RequestBody(required = false) com.fasterxml.jackson.databind.JsonNode request
    ) {
        AbstractProductResponseDto response = productService.patchProduct(productId, request);
        return ResponseEntity.ok(response);
    }

    @DeleteMapping()
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    @Override
    public ResponseEntity<String> deleteProduct(
            @RequestParam(name = "userId") String userId,
            @RequestParam(name = "productType") String productType,
            @RequestParam(name = "id") String id) {
        log.info("Received delete product request: {}", id);
        productService.deleteProduct(userId, id, productType);
        return ResponseEntity.status(HttpStatus.ACCEPTED).body("Product deleted succesfully: " + id);
    }

    @DeleteMapping("/{productId}")
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    public ResponseEntity<Void> deleteProduct(@PathVariable("productId") String productId) {
        productService.deleteProductById(productId);
        return ResponseEntity.noContent().build();
    }

    /**
     * EXPLORE endpoint
     * GET /api/products/search?term=foo&page=0&size=20
     */
    @GetMapping("/search")
    @Override
    public Page<ProductMinimised> exploreSearch(
            @RequestParam String term,
            @PageableDefault(size = 20, sort = "createdAt", direction = Sort.Direction.DESC) Pageable pageable
    ) {
        return productService.searchAllProducts(term, pageable);
    }

    /**
     * LIBRARY / TEACHER endpoint
     * GET /api/users/{userId}/products?term=foo&page=0&size=20
     */
    @GetMapping("/search/{userId}/products")
    @Override
    public Page<ProductMinimised> librarySearch(
            @PathVariable String userId,
            @RequestParam String term,
            @PageableDefault(size = 20, sort = "createdAt", direction = Sort.Direction.DESC)
            Pageable pageable
    ) {
        return productService.searchUserProducts(userId, term, pageable);
    }

}

import React, { useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate, useParams } from 'react-router-dom';
import DOMPurify from 'dompurify';
import { toast } from 'sonner';

import {
  AppDispatch,
  hasRole,
  ProductMinimised,
  RootState,
  UserRole,
} from 'core/api/models';
import {
  enrollInFreeProductAPI,
  getProductAccessAPI,
  getProductFileDownloadAPI,
} from 'core/api/services';
import { selectAuthUser } from 'core/store/auth-store';
import {
  clearCurrentProduct,
  getProductById,
  selectCurrentProduct,
  selectProductsError,
  selectProductsLoading,
} from 'core/store/product-store';
import {
  fetchPublicProductLandingPageConfig,
  selectPublicProductLandingPageConfigByProductId,
} from 'core/store/product-landing-page-store';
import {
  fetchPublicStorefront,
  selectCreatorStorefrontConfig,
  selectPublicStorefrontByCreatorId,
} from 'core/store/storefront-store';
import { addProductToCart, selectCartIds } from 'core/store/shop-cart';
import { Button, LegacyExpansionPanel } from '@shared/ui';
import {
  getProductLandingPageViewModel,
  isPublicProductLandingPageProduct,
  ProductLandingPage,
} from 'domains/app/features/product-landing-page';
import { appRoutes } from '../../routes/routes';

import './product-page.styles.scss';

const ProductPage: React.FC = () => {
  const { type, id } = useParams();
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const user = useSelector(selectAuthUser);
  const cartIds = useSelector(selectCartIds);
  const currentProduct = useSelector(selectCurrentProduct);
  const loading = useSelector(selectProductsLoading);
  const error = useSelector(selectProductsError);
  const creatorStorefrontConfig = useSelector(selectCreatorStorefrontConfig);
  const [hasAccess, setHasAccess] = useState(false);
  const [enrolling, setEnrolling] = useState(false);
  const loadedProduct =
    currentProduct?.id && currentProduct.id === id ? currentProduct : null;
  const publicStorefront = useSelector((state: RootState) =>
    selectPublicStorefrontByCreatorId(state, loadedProduct?.userId),
  );
  const landingPageConfig = useSelector((state: RootState) =>
    selectPublicProductLandingPageConfigByProductId(state, loadedProduct?.id),
  );
  const isOwner =
    Boolean(user?.id && user.id === loadedProduct?.userId) ||
    hasRole(user?.roles, UserRole.ADMIN);

  useEffect(() => {
    if (id) {
      dispatch(clearCurrentProduct());
      dispatch(getProductById({ productId: id }));
    }
  }, [dispatch, id]);

  useEffect(() => {
    if (loadedProduct && type && loadedProduct.type !== type) {
      navigate(appRoutes.product(loadedProduct.id), { replace: true });
    }
  }, [loadedProduct, navigate, type]);

  useEffect(() => {
    if (!user || !id) {
      setHasAccess(false);
      return;
    }

    getProductAccessAPI(id)
      .then((access) => setHasAccess(access.hasAccess))
      .catch(() => setHasAccess(false));
  }, [id, user]);

  useEffect(() => {
    if (
      loadedProduct?.userId &&
      isPublicProductLandingPageProduct(loadedProduct) &&
      !publicStorefront
    ) {
      dispatch(fetchPublicStorefront(loadedProduct.userId));
    }
  }, [dispatch, loadedProduct, publicStorefront]);

  useEffect(() => {
    if (loadedProduct && isPublicProductLandingPageProduct(loadedProduct)) {
      dispatch(fetchPublicProductLandingPageConfig(loadedProduct.id));
    }
  }, [dispatch, loadedProduct]);

  const viewModel = useMemo(() => {
    if (!loadedProduct || !isPublicProductLandingPageProduct(loadedProduct)) {
      return null;
    }

    return getProductLandingPageViewModel({
      product: loadedProduct,
      currentUser: user,
      publicStorefront,
      creatorStorefrontTheme: isOwner
        ? creatorStorefrontConfig?.theme
        : undefined,
      landingPageConfig,
    });
  }, [
    creatorStorefrontConfig?.theme,
    isOwner,
    landingPageConfig,
    loadedProduct,
    publicStorefront,
    user,
  ]);

  const numericPrice =
    loadedProduct?.price === 'free' ? 0 : Number(loadedProduct?.price ?? 0);
  const isFree = numericPrice === 0;
  const isMembershipProduct = loadedProduct?.type === 'MEMBERSHIP';
  const isInCart = Boolean(loadedProduct?.id && cartIds.has(loadedProduct.id));

  const toSummary = (): ProductMinimised | null => {
    if (!loadedProduct) {
      return null;
    }
    return {
      id: loadedProduct.id,
      title: loadedProduct.name,
      description: loadedProduct.description,
      type: loadedProduct.type,
      price: loadedProduct.price,
      status: loadedProduct.status,
      imageUrl: loadedProduct.imageUrl,
      createdById: loadedProduct.userId,
      createdAt: loadedProduct.createdAt,
      updatedAt: loadedProduct.updatedAt,
    };
  };

  const handleEnroll = async () => {
    if (!user) {
      navigate('/auth/login');
      return;
    }
    if (!loadedProduct) {
      return;
    }

    setEnrolling(true);
    try {
      await enrollInFreeProductAPI(loadedProduct.id);
      setHasAccess(true);
      await dispatch(getProductById({ productId: loadedProduct.id })).unwrap();
      toast.success('Added to your library');
    } catch {
      toast.error('This product could not be added to your library.');
    } finally {
      setEnrolling(false);
    }
  };

  const handleAddToCart = () => {
    const product = toSummary();
    if (product && !isInCart) {
      dispatch(addProductToCart(product));
    }
  };

  const handleDownload = async (fileId?: string) => {
    if (!loadedProduct || !fileId) {
      return;
    }
    try {
      const { url } = await getProductFileDownloadAPI(
        loadedProduct.id,
        fileId,
      );
      window.location.assign(url);
    } catch {
      toast.error('The download could not be started.');
    }
  };

  if (loading && !loadedProduct) {
    return (
      <main className="product-page-state" aria-busy="true">
        <h1>Loading Product</h1>
        <p>Preparing this Product page.</p>
      </main>
    );
  }

  if (error || !loadedProduct) {
    return (
      <main className="product-page-state" role="alert">
        <h1>Product unavailable</h1>
        <p>{error ?? 'This Product page could not be loaded.'}</p>
      </main>
    );
  }

  if (!viewModel) {
    return (
      <main className="product-page-state" role="alert">
        <h1>Product unavailable</h1>
        <p>This Product is not publicly available.</p>
      </main>
    );
  }

  const commerceActions = isOwner ? (
    <Button
      type="button"
      variant="primary"
      onClick={() => navigate(appRoutes.productsEdit(loadedProduct.id))}
    >
      Edit product
    </Button>
  ) : hasAccess ? (
    <Button type="button" variant="primary" disabled>
      In your library
    </Button>
  ) : isFree ? (
    <Button
      type="button"
      variant="primary"
      disabled={enrolling}
      onClick={handleEnroll}
    >
      {enrolling ? 'Adding...' : 'Enroll for free'}
    </Button>
  ) : isMembershipProduct ? (
    <Button type="button" variant="primary" disabled>
      Membership checkout unavailable
    </Button>
  ) : (
    <div className="product-page__commerce-actions">
      <Button
        type="button"
        variant="primary"
        disabled={isInCart}
        onClick={handleAddToCart}
      >
        {isInCart ? 'Already in cart' : 'Add to cart'}
      </Button>
      <Button
        type="button"
        variant="secondary"
        onClick={() => {
          handleAddToCart();
          navigate(appRoutes.cart);
        }}
      >
        Buy now
      </Button>
    </div>
  );

  return (
    <>
      <ProductLandingPage product={viewModel} commerceActions={commerceActions} />
      {(hasAccess || isOwner) && loadedProduct.type === 'COURSE' && (
        <section className="product-page__protected-content">
          <h2>Course content</h2>
          {loadedProduct.sections?.map((section) => (
            <LegacyExpansionPanel key={section.id} header={section.title || ''}>
              {section.description && <p>{section.description}</p>}
              {section.lessons?.map((lesson) => (
                <article key={lesson.id} className="product-page__lesson">
                  <h3>{lesson.title}</h3>
                  {lesson.content && (
                    <div
                      dangerouslySetInnerHTML={{
                        __html: DOMPurify.sanitize(lesson.content),
                      }}
                    />
                  )}
                  {lesson.videoUrl && (
                    <video controls src={lesson.videoUrl}>
                      <track kind="captions" />
                    </video>
                  )}
                </article>
              ))}
            </LegacyExpansionPanel>
          ))}
        </section>
      )}
      {(hasAccess || isOwner) && loadedProduct.type === 'DOWNLOAD' && (
        <section className="product-page__protected-content">
          <h2>Downloads</h2>
          {loadedProduct.sections?.map((section) => (
            <LegacyExpansionPanel key={section.id} header={section.title || ''}>
              {section.files?.map((file) => (
                <button
                  key={file.id}
                  type="button"
                  className="product-page__download"
                  onClick={() => handleDownload(file.id)}
                >
                  {file.fileName}
                </button>
              ))}
            </LegacyExpansionPanel>
          ))}
        </section>
      )}
    </>
  );
};

export default ProductPage;

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

import {
  ProductEntitlement,
  ProductType,
} from 'core/api/models';
import { getMyEntitlementsAPI } from 'core/api/services';
import { Button } from '@shared/ui';
// eslint-disable-next-line @typescript-eslint/no-var-requires
const placeholderImage = require('../../../../../assets/image-placeholder.png');

import './library-page.styles.scss';

interface LibraryProductsProps {
  type?: ProductType;
}

const LibraryProducts: React.FC<LibraryProductsProps> = ({ type }) => {
  const navigate = useNavigate();
  const [entitlements, setEntitlements] = useState<ProductEntitlement[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let mounted = true;
    setLoading(true);
    setError(null);

    getMyEntitlementsAPI({ type })
      .then((result) => {
        if (mounted) {
          setEntitlements(result);
        }
      })
      .catch(() => {
        if (mounted) {
          setError('Your library could not be loaded.');
        }
      })
      .finally(() => {
        if (mounted) {
          setLoading(false);
        }
      });

    return () => {
      mounted = false;
    };
  }, [type]);

  if (loading) {
    return <p>Loading your library...</p>;
  }

  if (error) {
    return <p role="alert">{error}</p>;
  }

  if (entitlements.length === 0) {
    return <p>You do not have any products in this section yet.</p>;
  }

  return (
    <div className="library-products">
      {entitlements.map(({ id, product }) => (
        <article key={id} className="library-product">
          <img
            src={product.imageUrl || placeholderImage}
            alt={product.title || 'Product'}
          />
          <div>
            <h2>{product.title || 'Untitled product'}</h2>
            <p>{product.type}</p>
            <p>{product.description}</p>
          </div>
          <Button
            type="button"
            variant="primary"
            onClick={() => navigate(`/app/product/${product.id}`)}
          >
            Open
          </Button>
        </article>
      ))}
    </div>
  );
};

export default LibraryProducts;

