import React, { useEffect, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate, useParams } from 'react-router-dom';

import { Button, StatusBadge, StatusBadgeTone } from '@shared/ui';
import {
  AppDispatch,
  hasRole,
  ProductStatus,
  RootState,
  UserRole,
} from 'core/api/models';
import { selectAuthUser } from 'core/store/auth-store';
import {
  clearCurrentProduct,
  getProductById,
  selectCurrentProduct,
  selectProductsError,
  selectProductsLoading,
} from 'core/store/product-store';
import {
  fetchCreatorProductLandingPageConfig,
  selectCreatorProductLandingPageConfigByProductId,
  selectCreatorProductLandingPageConfigError,
  selectCreatorProductLandingPageConfigLoading,
} from 'core/store/product-landing-page-store';
import {
  fetchCreatorStorefrontConfig,
  fetchPublicStorefront,
  selectCreatorStorefrontConfig,
  selectCreatorStorefrontConfigError,
  selectCreatorStorefrontConfigLoading,
  selectPublicStorefrontByCreatorId,
  selectPublicStorefrontLoading,
} from 'core/store/storefront-store';
import {
  getProductLandingPageViewModel,
  ProductLandingPage,
} from 'domains/app/features/product-landing-page';
import { appRoutes } from 'domains/app/routes/routes';
import { getProductStatusLabel } from '../products-list/products-list.utils';

import './product-preview.styles.scss';

const productStatusTone: Record<ProductStatus, StatusBadgeTone> = {
  PUBLISHED: 'success',
  DRAFT: 'neutral',
  HIDDEN: 'warning',
};

const ProductPreview: React.FC = () => {
  const { productId } = useParams();
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const user = useSelector(selectAuthUser);
  const product = useSelector(selectCurrentProduct);
  const productLoading = useSelector(selectProductsLoading);
  const productError = useSelector(selectProductsError);
  const creatorStorefrontConfig = useSelector(selectCreatorStorefrontConfig);
  const creatorStorefrontLoading = useSelector(selectCreatorStorefrontConfigLoading);
  const creatorStorefrontError = useSelector(selectCreatorStorefrontConfigError);
  const publicStorefrontLoading = useSelector(selectPublicStorefrontLoading);
  const landingPageConfig = useSelector((state: RootState) =>
    selectCreatorProductLandingPageConfigByProductId(state, productId),
  );
  const landingPageConfigLoading = useSelector(
    selectCreatorProductLandingPageConfigLoading,
  );
  const landingPageConfigError = useSelector(
    selectCreatorProductLandingPageConfigError,
  );
  const loadedProduct = product?.id === productId ? product : null;
  const isCreatorOwner = Boolean(
    loadedProduct?.userId &&
      user?.id === loadedProduct.userId &&
      hasRole(user?.roles, UserRole.CREATOR),
  );
  const shouldUsePublicStorefront = Boolean(
    loadedProduct?.userId && !isCreatorOwner,
  );
  const publicStorefront = useSelector((state: RootState) =>
    selectPublicStorefrontByCreatorId(state, loadedProduct?.userId),
  );

  useEffect(() => {
    dispatch(clearCurrentProduct());

    if (productId) {
      dispatch(getProductById({ productId }));
      dispatch(fetchCreatorProductLandingPageConfig(productId));
    }
  }, [dispatch, productId]);

  useEffect(() => {
    if (!loadedProduct?.userId) {
      return;
    }

    if (isCreatorOwner) {
      dispatch(fetchCreatorStorefrontConfig());
      return;
    }

    if (!publicStorefront) {
      dispatch(fetchPublicStorefront(loadedProduct.userId));
    }
  }, [dispatch, isCreatorOwner, loadedProduct, publicStorefront]);

  const viewModel = useMemo(() => {
    if (!loadedProduct) {
      return null;
    }

    return getProductLandingPageViewModel({
      product: loadedProduct,
      currentUser: user,
      publicStorefront: shouldUsePublicStorefront ? publicStorefront : undefined,
      creatorStorefrontTheme: isCreatorOwner
        ? creatorStorefrontConfig?.theme
        : undefined,
      landingPageConfig,
    });
  }, [
    creatorStorefrontConfig?.theme,
    isCreatorOwner,
    landingPageConfig,
    loadedProduct,
    publicStorefront,
    shouldUsePublicStorefront,
    user,
  ]);

  const handleBackToWorkspace = () => {
    if (loadedProduct?.id ?? productId) {
      navigate(appRoutes.productsEdit(loadedProduct?.id ?? productId));
      return;
    }

    navigate(appRoutes.products);
  };

  if (!productId) {
    return (
      <main className="product-preview product-preview--state" role="alert">
        <h1>Product preview unavailable</h1>
        <p>This preview route is missing a Product ID.</p>
        <Button type="button" variant="secondary" onClick={() => navigate(appRoutes.products)}>
          Back to Products
        </Button>
      </main>
    );
  }

  const storefrontLoading = isCreatorOwner
    ? creatorStorefrontLoading
    : publicStorefrontLoading && shouldUsePublicStorefront && !publicStorefront;
  const loadError = productError ?? landingPageConfigError ??
    (isCreatorOwner ? creatorStorefrontError : null);

  if (
    ((productLoading || landingPageConfigLoading || storefrontLoading) &&
      !loadedProduct) ||
    (!loadedProduct && !loadError)
  ) {
    return (
      <main className="product-preview product-preview--state" aria-busy="true">
        <h1>Loading Product preview</h1>
        <p>Preparing the creator-only preview.</p>
      </main>
    );
  }

  if (loadError || !loadedProduct || !viewModel) {
    return (
      <main className="product-preview product-preview--state" role="alert">
        <h1>Product preview unavailable</h1>
        <p>{loadError ?? 'This Product could not be loaded for preview.'}</p>
        <Button type="button" variant="secondary" onClick={() => navigate(appRoutes.products)}>
          Back to Products
        </Button>
      </main>
    );
  }

  const productStatus = loadedProduct.status ?? 'DRAFT';
  const statusLabel = getProductStatusLabel(productStatus);

  return (
    <main className="product-preview">
      <div className="product-preview__bar" role="status">
        <div className="product-preview__bar-copy">
          <StatusBadge
            label={statusLabel}
            tone={productStatusTone[productStatus] ?? 'neutral'}
            size="sm"
          />
          <div>
            <p>{statusLabel} Product preview</p>
            <span>
              This creator-only preview is available for Draft, Hidden, and
              Published Products. Public visibility is controlled separately.
            </span>
          </div>
        </div>
        <Button
          type="button"
          variant="secondary"
          size="sm"
          onClick={handleBackToWorkspace}
        >
          Back to workspace
        </Button>
      </div>

      <ProductLandingPage product={viewModel} />
    </main>
  );
};

export default ProductPreview;

package com.myproject.video.video_platform.service.product;

import com.myproject.video.video_platform.common.enums.products.ProductStatus;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.products.consultation.ConsultationAvailabilityDay;
import com.myproject.video.video_platform.entity.products.consultation.ConsultationAvailabilityWindow;
import com.myproject.video.video_platform.entity.products.consultation.ConsultationProduct;
import com.myproject.video.video_platform.entity.products.course.CourseProduct;
import com.myproject.video.video_platform.entity.products.download.DownloadProduct;
import com.myproject.video.video_platform.entity.products.membership.MembershipProduct;
import com.myproject.video.video_platform.exception.product.ProductPublicationValidationException;
import org.springframework.stereotype.Component;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Component
public class ProductPublicationValidator {
    public void validate(Product product) {
        if (product.getStatus() != ProductStatus.PUBLISHED) return;
        Map<String, String> issues = new LinkedHashMap<>();
        if (product.getName() == null || product.getName().isBlank()) {
            issues.put("name", "Name is required");
        }
        if (product instanceof MembershipProduct) {
            issues.put("status", "Membership publication is not supported yet");
        } else if (product instanceof CourseProduct course) {
            requireFreeOrPositivePrice(product, issues);
            if (course.getSections() == null || course.getSections().isEmpty()) {
                issues.put("details.sections", "At least one section is required");
            } else if (course.getSections().stream().noneMatch(s -> s.getLessons() != null && !s.getLessons().isEmpty())) {
                issues.put("details.lessons", "At least one lesson is required");
            }
        } else if (product instanceof DownloadProduct download) {
            requireFreeOrPositivePrice(product, issues);
            boolean hasFile = download.getSectionDownloadProducts() != null
                    && download.getSectionDownloadProducts().stream()
                    .flatMap(section -> section.getFiles().stream())
                    .anyMatch(file -> file.getPath() != null && !file.getPath().isBlank());
            if (!hasFile) issues.put("details.files", "At least one confirmed file is required");
        } else if (product instanceof ConsultationProduct consultation) {
            if (product.getPrice() == null || product.getPrice().compareTo(BigDecimal.ZERO) <= 0) {
                issues.put("price", "Consultations require a positive price");
            }
            if (consultation.getDurationMinutes() == null || consultation.getDurationMinutes() <= 0) {
                issues.put("details.durationMinutes", "Duration must be positive");
            }
            if (consultation.getMeetingMethod() == null) {
                issues.put("details.meetingMethod", "Meeting method is required");
            } else if (consultation.getMeetingMethod() == ConsultationProduct.MeetingMethod.OTHER
                    && (consultation.getCustomLocation() == null || consultation.getCustomLocation().isBlank())) {
                issues.put("details.customLocation", "A custom location is required for OTHER");
            }
            validateAvailability(consultation, issues);
        }
        if (!issues.isEmpty()) throw new ProductPublicationValidationException(issues);
    }

    private static void requireFreeOrPositivePrice(Product product, Map<String, String> issues) {
        if (product.getPrice() == null || product.getPrice().compareTo(BigDecimal.ZERO) < 0) {
            issues.put("price", "Price must be free or positive");
        }
    }

    private static void validateAvailability(ConsultationProduct product, Map<String, String> issues) {
        boolean validRangeFound = false;
        for (ConsultationAvailabilityDay day : product.getWeeklyAvailability()) {
            if (!day.isEnabled()) continue;
            List<ConsultationAvailabilityWindow> windows = day.getWindows();
            for (int index = 0; index < windows.size(); index++) {
                ConsultationAvailabilityWindow current = windows.get(index);
                if (!current.getStartTime().isBefore(current.getEndTime())) {
                    issues.put("details.weeklyAvailability", "Availability start time must be before end time");
                    continue;
                }
                validRangeFound = true;
                for (int other = index + 1; other < windows.size(); other++) {
                    ConsultationAvailabilityWindow candidate = windows.get(other);
                    if (current.getStartTime().isBefore(candidate.getEndTime())
                            && candidate.getStartTime().isBefore(current.getEndTime())) {
                        issues.put("details.weeklyAvailability", "Availability windows cannot overlap");
                    }
                }
            }
        }
        if (!validRangeFound) {
            issues.put("details.weeklyAvailability", "At least one enabled valid availability range is required");
        }
    }
}

