  marketingDescription: '',
  heroLayout: 'MEDIA_RIGHT',
  visibleSections: ['CONTENTS', 'CREATOR'],
  sectionOrder: PRODUCT_LANDING_PAGE_SECTIONS,
};

export const productLandingPageSectionLabels: Record<
  ProductLandingPageSectionId,
  string
