const normalizeDraftConfig = (
  config: DraftStorefrontConfig | null | undefined,
): DraftStorefrontConfig => ({
  featuredProductId: config?.featuredProductId ?? null,
  productOrderIds: config?.productOrderIds ?? [],
  theme: config?.theme ?? DEFAULT_STOREFRONT_THEME,
});

const getDisplayNamePayload = (displayName: string): UpdateUserRequest => {
  const [firstName = '', ...rest] = displayName.trim().split(/\s+/);
  return {
    firstName,
    lastName: rest.join(' '),
  };
};

interface InlineProfileEditorProps {
  label: string;
  value: string;
  fallback?: string;
  multiline?: boolean;
  helpText?: string;
  saving?: boolean;
  onSave: (value: string) => Promise<void>;
}

const InlineProfileEditor: React.FC<InlineProfileEditorProps> = ({
  label,
  value,
  fallback = 'Not set',
  multiline = false,
  helpText,
  saving = false,
  onSave,
}) => {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(value);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!editing) {
      setDraft(value);
    }
  }, [editing, value]);

  const cancel = () => {
    setDraft(value);
    setError(null);
    setEditing(false);
  };

  const save = async () => {
    try {
      await onSave(draft.trim());
      setError(null);
      setEditing(false);
    } catch {
      setError(`Unable to save ${label.toLowerCase()}.`);
    }
  };

  if (editing) {
    return (
      <span className="storefront-inline-edit storefront-inline-edit--active">
        {multiline ? (
          <Textarea
            aria-label={label}
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            block
          />
        ) : (
          <Input
            aria-label={label}
            name={`storefront-${label}`}
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
          />
        )}
        <span className="storefront-inline-edit__actions">
          <Button
            type="button"
            variant="primary"
            size="sm"
            loading={saving}
            onClick={save}
            leadingIcon={<Icon icon={FiCheck} color="currentColor" />}
          >
            Save
          </Button>
          <Button
            type="button"
            variant="secondary"
            size="sm"
            disabled={saving}
            onClick={cancel}
            leadingIcon={<Icon icon={FiX} color="currentColor" />}
          >
            Cancel
          </Button>
        </span>
        {error && <span className="storefront-inline-edit__error">{error}</span>}
      </span>
    );
  }

  return (
    <span className="storefront-inline-edit">
      <span>{value || fallback}</span>
      {helpText && (
        <InfoPopover className="storefront-inline-edit__popover">
          <span>{helpText}</span>
        </InfoPopover>
      )}
      <Button
        type="button"
        variant="ghost"
        size="icon"
        aria-label={`Edit ${label}`}
        onClick={() => setEditing(true)}
      >
        <Icon icon={FiEdit3} color="currentColor" size={15} />
      </Button>
    </span>
  );
};

const CreatorStorefrontPage: React.FC = () => {
