const getGreeting = (firstName?: string) => {
  const hour = new Date().getHours();
  const dayPart =
    hour < 12 ? 'morning' : hour < 18 ? 'afternoon' : 'evening';

  return `Good ${dayPart}, ${firstName || 'creator'}.`;
};

const unavailableDashboard: CreatorDashboardSummary = {
  metrics: [
    {
      id: 'revenue',
      label: 'Revenue',
      value: '',
      state: 'unavailable',
    },
    {
      id: 'sales',
      label: 'Sales',
      value: '',
      state: 'unavailable',
    },
    {
      id: 'customers',
      label: 'Customers',
      value: '',
      state: 'unavailable',
    },
    {
      id: 'active-memberships',
      label: 'Active memberships',
      value: '',
      state: 'unavailable',
    },
  ],
  activities: [],
  topProducts: [],
  attentionItems: [],
};

const CreatorDashboard: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const user = useSelector(selectAuthUser);
  const isCreator = hasRole(user?.roles, UserRole.CREATOR);
  const dashboard = useSelector(selectCreatorDashboardSummary);
  const isLoading = useSelector(selectCreatorDashboardLoading);
  const error = useSelector(selectCreatorDashboardError);

  useEffect(() => {
    if (isCreator) {
      dispatch(fetchCreatorDashboardSummary());
    }
  }, [dispatch, isCreator]);

  if (!isCreator) {
    return (
      <section className="creator-dashboard creator-dashboard__empty">
        <h1>Dashboard</h1>
        <p>Creator business tools are available when your active role is Creator.</p>
      </section>
    );
  }

  const dashboardSummary = error || !dashboard ? unavailableDashboard : dashboard;

  return (
    <div className="creator-dashboard">
      <header className="creator-dashboard__intro">
        <div>
          <h1>Dashboard</h1>
          <p>{getGreeting(user?.firstName)}</p>
        </div>
      </header>

      <section className="creator-dashboard__metrics" aria-label="Business metrics">
        {dashboardSummary.metrics.map((metric) => (
          <MetricCard
            key={metric.id}
            metric={isLoading && !dashboard ? { ...metric, state: 'loading' } : metric}
          />
        ))}
      </section>

      <div className="creator-dashboard__grid">
        <section className="dashboard-panel dashboard-panel__activity">
          <div className="dashboard-panel__header">
            <h2>Recent activity</h2>
          </div>
          {dashboardSummary.activities.length > 0 ? (
            <ActivityList items={dashboardSummary.activities} />
          ) : (
            <p className="dashboard-panel__empty">
              Activity will appear here once business events are available.
            </p>
          )}
        </section>

        <section className="dashboard-panel dashboard-panel__products">
          <div className="dashboard-panel__header">
            <h2>Top products</h2>
            <span>Revenue</span>
          </div>
          {dashboardSummary.topProducts.length > 0 ? (
            <ProductPerformanceList items={dashboardSummary.topProducts} />
          ) : (
            <p className="dashboard-panel__empty">
              Product performance is unavailable until revenue data exists.
            </p>
          )}
        </section>

        <section className="dashboard-panel dashboard-panel__attention">
          <div className="dashboard-panel__header">
            <h2>Needs attention</h2>
          </div>
          {dashboardSummary.attentionItems.length > 0 ? (
            <AttentionList items={dashboardSummary.attentionItems} />
          ) : (
            <p className="dashboard-panel__empty">
              No deterministic attention states are available yet.
            </p>
          )}
        </section>
      </div>
    </div>
  );
};

export default CreatorDashboard;

import React from 'react';
import clsx from 'clsx';
import { Link } from 'react-router-dom';

import {
  DashboardMetric,
  DashboardMetricDirection,
  DashboardMetricSentiment,
} from 'core/api/models';

import './metric-card.styles.scss';

const directionSymbol: Record<DashboardMetricDirection, string> = {
  up: '↑',
  down: '↓',
  flat: '—',
};

const directionAriaLabel: Record<DashboardMetricDirection, string> = {
  up: 'Up',
  down: 'Down',
  flat: 'No change',
};

const formatComparison = (
  direction: DashboardMetricDirection,
  comparison: string,
) => {
  const conciseComparison =
    direction === 'flat' ? comparison : comparison.replace(/^[+-]\s*/, '');

  return `${directionSymbol[direction]} ${conciseComparison}`;
};

const sentimentAriaLabel: Record<DashboardMetricSentiment, string> = {
  favorable: 'positive',
  unfavorable: 'needs attention',
  neutral: 'neutral',
};

const displayMetricLabel = (metric: DashboardMetric) =>
  metric.id === 'active-memberships' ? (
    <>
      <span className="metric-card__label-full">Active memberships</span>
      <span className="metric-card__label-short" aria-hidden="true">
        Memberships
      </span>
    </>
  ) : (
    metric.label
  );

interface MetricCardProps {
  metric: DashboardMetric;
}

const MetricCard: React.FC<MetricCardProps> = ({ metric }) => {
  const state = metric.state ?? 'ready';
  const isInteractive = state === 'ready' && Boolean(metric.destinationPath);

  if (state === 'loading') {
    return (
      <article className="metric-card metric-card__loading" aria-busy="true">
        <span className="metric-card__label" aria-label={metric.label}>
          {displayMetricLabel(metric)}
        </span>
        <span className="metric-card__skeleton metric-card__skeleton-value" />
        <span className="metric-card__skeleton metric-card__skeleton-meta" />
      </article>
    );
  }

  if (state === 'unavailable') {
    return (
      <article className="metric-card metric-card__unavailable">
        <span className="metric-card__label" aria-label={metric.label}>
          {displayMetricLabel(metric)}
        </span>
        <strong className="metric-card__value">Unavailable</strong>
        <span className="metric-card__comparison">
          More business data is needed.
        </span>
      </article>
    );
  }

  const direction = metric.direction ?? 'flat';
  const sentiment = metric.sentiment ?? 'neutral';
  const comparison = metric.comparison
    ? formatComparison(direction, metric.comparison)
    : '';

  const content = (
    <>
      <span className="metric-card__label" aria-label={metric.label}>
        {displayMetricLabel(metric)}
      </span>
      <strong className="metric-card__value">{metric.value}</strong>
      {metric.comparison && (
        <span className="metric-card__comparison">
          <span className="metric-card__trend-mark" aria-hidden="true" />
          <span
            className="metric-card__comparison-text"
            aria-label={`${directionAriaLabel[direction]} ${sentimentAriaLabel[sentiment]} trend: ${metric.comparison}`}
          >
            {comparison}
          </span>
        </span>
      )}
    </>
  );

  const className = clsx(
    'metric-card',
    `metric-card__${sentiment}`,
    isInteractive && 'metric-card__interactive',
  );

  if (isInteractive && metric.destinationPath) {
    return (
      <Link
        className={className}
        to={metric.destinationPath}
        aria-label={`View ${metric.label} details`}
      >
        {content}
      </Link>
    );
  }

  return <article className={className}>{content}</article>;
};

export default MetricCard;

