];

const CreatorAnalytics: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const [period, setPeriod] = useState<AnalyticsPeriod>('30d');
  const [performanceMode, setPerformanceMode] =
    useState<AnalyticsMetricKey>('revenue');
