        <Select
          name="analytics-period"
          value={period}
          options={analyticsPeriodOptions}
          onChange={handlePeriodChange}
          customClassName="creator-analytics__period"
          prefixIcon={MdOutlineCalendarToday}
          aria-label="Select analytics date range"
