import { useState, useRef, useEffect, useCallback } from 'react';

import { selectAuthUser } from 'core/store/auth-store';
import { updateProductDetails } from 'core/store/product-store';
import { ProductDraft } from '../models/product-form';
import {
  getAutosaveSnapshot,
  mapFormDataToProductPayload,
} from '../utils/form-data-mapper.utils';
import { AppDispatch } from 'core/api/models';

interface UseProductAutosaveParams {
  formData: ProductDraft;
  user: ReturnType<typeof selectAuthUser> | null;
  showRestOfForm: boolean;
  dispatch: AppDispatch;
}

export const useProductAutosave = ({
  formData,
  user,
  showRestOfForm,
  dispatch,
}: UseProductAutosaveParams) => {
  const [isAutosaving, setIsAutosaving] = useState(false);
  const [hasPendingAutosave, setHasPendingAutosave] = useState(false);
  const [lastSavedAt, setLastSavedAt] = useState<Date | null>(null);
  const lastSavedSnapshot = useRef<Partial<ProductDraft> | null>(null);
  const timeoutRef = useRef<number | null>(null);

  const clearPendingTimeout = useCallback(() => {
    if (timeoutRef.current) {
      window.clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
  }, []);

  const saveProduct = useCallback(
    async (snapshot: Partial<ProductDraft>) => {
      const productData = mapFormDataToProductPayload(formData, user);

      setIsAutosaving(true);
      setHasPendingAutosave(false);

      try {
        await dispatch(updateProductDetails(productData)).unwrap();
        lastSavedSnapshot.current = snapshot;
        setLastSavedAt(new Date());
      } catch (error) {
        console.error('Autosave failed:', error);
        throw error;
      } finally {
        setIsAutosaving(false);
      }
    },
    [dispatch, formData, user],
  );

  const flushAutosave = useCallback(async () => {
    if (!formData.id || !user?.id || !showRestOfForm) {
      return;
    }

    const currentSnapshot = getAutosaveSnapshot(formData);
    const hasChanges =
      JSON.stringify(currentSnapshot) !==
      JSON.stringify(lastSavedSnapshot.current);

    if (!hasChanges) {
      clearPendingTimeout();
      setHasPendingAutosave(false);
      return;
    }

    clearPendingTimeout();
    await saveProduct(currentSnapshot);
  }, [clearPendingTimeout, formData, saveProduct, showRestOfForm, user?.id]);

  useEffect(() => {
    if (!formData.id) {
      return;
    }
    if (!user || !user.id) {
      return;
    }
    if (!showRestOfForm) {
      return;
    }

    const currentSnapshot = getAutosaveSnapshot(formData);

    if (!lastSavedSnapshot.current) {
      lastSavedSnapshot.current = currentSnapshot;
      return;
    }

    const hasChanges =
      JSON.stringify(currentSnapshot) !==
      JSON.stringify(lastSavedSnapshot.current);

    if (!hasChanges) {
      return;
    }

    setHasPendingAutosave(true);

    const timeoutId = window.setTimeout(() => {
      try {
        void saveProduct(currentSnapshot).catch(() => undefined);
      } catch (e) {
        console.error('Autosave mapping error:', e);
        setHasPendingAutosave(false);
        setIsAutosaving(false);
      }
    }, 2000);
    timeoutRef.current = timeoutId;

    return () => {
      if (timeoutRef.current === timeoutId) {
        timeoutRef.current = null;
      }
      window.clearTimeout(timeoutId);
    };
  }, [formData, user, showRestOfForm, saveProduct]);

  return { isAutosaving, hasPendingAutosave, lastSavedAt, flushAutosave };
};

import { useRef, useState, useEffect } from 'react';

import { AbstractProduct, AppDispatch } from 'core/api/models';
import { getProductById } from 'core/store/product-store';
import { ProductDraft, FormErrors } from '../models/product-form';
import { getAutosaveSnapshot } from '../utils/form-data-mapper.utils';

interface UseProductLoaderParams {
  isEditMode: boolean;
  id?: string;
  dispatch: AppDispatch;
  // eslint-disable-next-line no-unused-vars
  setFormData: (data: ProductDraft) => void;
  // eslint-disable-next-line no-unused-vars
  setErrors: (errors: FormErrors) => void;
  // eslint-disable-next-line no-unused-vars
  setShowRestOfForm: (value: boolean) => void;
  // eslint-disable-next-line no-unused-vars
  onProductLoaded?: (product: AbstractProduct) => void;
}

export const useProductLoader = ({
  isEditMode,
  id,
  dispatch,
  setFormData,
  setErrors,
  setShowRestOfForm,
  onProductLoaded,
}: UseProductLoaderParams) => {
  const lastSavedSnapshot = useRef<Partial<ProductDraft> | null>(null);
  const [, setLastSavedAt] = useState<Date | null>(null); // you can also lift this up if needed

  useEffect(() => {
    if (!isEditMode || !id) {
      return;
    }

    dispatch(getProductById({ productId: id }))
      .unwrap()
      .then((product) => {
        const baseData = {
          id: product.id ?? '',
          name: product.name ?? '',
          description: product.description ?? '',
          type: product.type ?? 'COURSE',
          price: product.price ?? 'free',
          pricingModel: product.pricingModel,
          billingInterval: product.billingInterval,
          currency: product.currency,
          status: product.status,
          imageUrl: product.imageUrl,
          galleryImages: product.galleryImages,
          promoVideo: product.promoVideo,
          userId: product.userId,
        };

        let newData: ProductDraft = baseData;

        if (product.type === 'COURSE' || product.type === 'DOWNLOAD') {
          newData = {
            ...baseData,
            sections: product.sections || [],
          };
        } else if (product.type === 'CONSULTATION') {
          newData = {
            ...baseData,
            consultationDetails: product.consultationDetails,
          };
        } else if (product.type === 'MEMBERSHIP') {
          newData = baseData;
        }

        setFormData(newData);
        lastSavedSnapshot.current = getAutosaveSnapshot(newData);
        setLastSavedAt(new Date());
        setShowRestOfForm(true);
        onProductLoaded?.(product);
      })
      .catch((error) => {
        // eslint-disable-next-line no-console
        console.error('Failed to load product data', error);
        setErrors({ api: 'Could not load product data' });
      });
  }, [
    dispatch,
    id,
    isEditMode,
    setFormData,
    setErrors,
    setShowRestOfForm,
    onProductLoaded,
  ]);

  return { lastSavedSnapshot };
};

import React, { useEffect, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate, useParams } from 'react-router-dom';

import { Button, StatusBadge, StatusBadgeTone } from '@shared/ui';
import {
  AppDispatch,
  hasRole,
  ProductStatus,
  RootState,
  UserRole,
} from 'core/api/models';
import { selectAuthUser } from 'core/store/auth-store';
import {
  clearCurrentProduct,
  getProductById,
  selectCurrentProduct,
  selectProductsError,
  selectProductsLoading,
} from 'core/store/product-store';
import {
  fetchCreatorProductLandingPageConfig,
  selectCreatorProductLandingPageConfigByProductId,
  selectCreatorProductLandingPageConfigError,
  selectCreatorProductLandingPageConfigLoading,
} from 'core/store/product-landing-page-store';
import {
  fetchCreatorStorefrontConfig,
  fetchPublicStorefront,
  selectCreatorStorefrontConfig,
  selectCreatorStorefrontConfigError,
  selectCreatorStorefrontConfigLoading,
  selectPublicStorefrontByCreatorId,
  selectPublicStorefrontLoading,
} from 'core/store/storefront-store';
import {
  getProductLandingPageViewModel,
  ProductLandingPage,
} from 'domains/app/features/product-landing-page';
import { appRoutes } from 'domains/app/routes/routes';
import { getProductStatusLabel } from '../products-list/products-list.utils';

import './product-preview.styles.scss';

const productStatusTone: Record<ProductStatus, StatusBadgeTone> = {
  PUBLISHED: 'success',
  DRAFT: 'neutral',
  HIDDEN: 'warning',
};

const ProductPreview: React.FC = () => {
  const { productId } = useParams();
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const user = useSelector(selectAuthUser);
  const product = useSelector(selectCurrentProduct);
  const productLoading = useSelector(selectProductsLoading);
  const productError = useSelector(selectProductsError);
  const creatorStorefrontConfig = useSelector(selectCreatorStorefrontConfig);
  const creatorStorefrontLoading = useSelector(selectCreatorStorefrontConfigLoading);
  const creatorStorefrontError = useSelector(selectCreatorStorefrontConfigError);
  const publicStorefrontLoading = useSelector(selectPublicStorefrontLoading);
  const landingPageConfig = useSelector((state: RootState) =>
    selectCreatorProductLandingPageConfigByProductId(state, productId),
  );
  const landingPageConfigLoading = useSelector(
    selectCreatorProductLandingPageConfigLoading,
  );
  const landingPageConfigError = useSelector(
    selectCreatorProductLandingPageConfigError,
  );
  const loadedProduct = product?.id === productId ? product : null;
  const isCreatorOwner = Boolean(
    loadedProduct?.userId &&
      user?.id === loadedProduct.userId &&
      hasRole(user?.roles, UserRole.CREATOR),
  );
  const shouldUsePublicStorefront = Boolean(
    loadedProduct?.userId && !isCreatorOwner,
  );
  const publicStorefront = useSelector((state: RootState) =>
    selectPublicStorefrontByCreatorId(state, loadedProduct?.userId),
  );

  useEffect(() => {
    dispatch(clearCurrentProduct());

    if (productId) {
      dispatch(getProductById({ productId }));
      dispatch(fetchCreatorProductLandingPageConfig(productId));
    }
  }, [dispatch, productId]);

  useEffect(() => {
    if (!loadedProduct?.userId) {
      return;
    }

    if (isCreatorOwner) {
      dispatch(fetchCreatorStorefrontConfig());
      return;
    }

    if (!publicStorefront) {
      dispatch(fetchPublicStorefront(loadedProduct.userId));
    }
  }, [dispatch, isCreatorOwner, loadedProduct, publicStorefront]);

  const viewModel = useMemo(() => {
    if (!loadedProduct) {
      return null;
    }

    return getProductLandingPageViewModel({
      product: loadedProduct,
      currentUser: user,
      publicStorefront: shouldUsePublicStorefront ? publicStorefront : undefined,
      creatorStorefrontTheme: isCreatorOwner
        ? creatorStorefrontConfig?.theme
        : undefined,
      landingPageConfig,
    });
  }, [
    creatorStorefrontConfig?.theme,
    isCreatorOwner,
    landingPageConfig,
    loadedProduct,
    publicStorefront,
    shouldUsePublicStorefront,
    user,
  ]);

  const handleBackToWorkspace = () => {
    if (loadedProduct?.id ?? productId) {
      navigate(appRoutes.productsEdit(loadedProduct?.id ?? productId));
      return;
    }

    navigate(appRoutes.products);
  };

  if (!productId) {
    return (
      <main className="product-preview product-preview--state" role="alert">
        <h1>Product preview unavailable</h1>
        <p>This preview route is missing a Product ID.</p>
        <Button type="button" variant="secondary" onClick={() => navigate(appRoutes.products)}>
          Back to Products
        </Button>
      </main>
    );
  }

  const storefrontLoading = isCreatorOwner
    ? creatorStorefrontLoading
    : publicStorefrontLoading && shouldUsePublicStorefront && !publicStorefront;
  const loadError = productError ?? landingPageConfigError ??
    (isCreatorOwner ? creatorStorefrontError : null);

  if (
    ((productLoading || landingPageConfigLoading || storefrontLoading) &&
      !loadedProduct) ||
    (!loadedProduct && !loadError)
  ) {
    return (
      <main className="product-preview product-preview--state" aria-busy="true">
        <h1>Loading Product preview</h1>
        <p>Preparing the creator-only preview.</p>
      </main>
    );
  }

  if (loadError || !loadedProduct || !viewModel) {
    return (
      <main className="product-preview product-preview--state" role="alert">
        <h1>Product preview unavailable</h1>
        <p>{loadError ?? 'This Product could not be loaded for preview.'}</p>
        <Button type="button" variant="secondary" onClick={() => navigate(appRoutes.products)}>
          Back to Products
        </Button>
      </main>
    );
  }

  const productStatus = loadedProduct.status ?? 'DRAFT';
  const statusLabel = getProductStatusLabel(productStatus);

  return (
    <main className="product-preview">
      <div className="product-preview__bar" role="status">
        <div className="product-preview__bar-copy">
          <StatusBadge
            label={statusLabel}
            tone={productStatusTone[productStatus] ?? 'neutral'}
            size="sm"
          />
          <div>
            <p>{statusLabel} Product preview</p>
            <span>
              This creator-only preview is available for Draft, Hidden, and
              Published Products. Public visibility is controlled separately.
            </span>
          </div>
        </div>
        <Button
          type="button"
          variant="secondary"
          size="sm"
          onClick={handleBackToWorkspace}
        >
          Back to workspace
        </Button>
      </div>

      <ProductLandingPage product={viewModel} />
    </main>
  );
};

