export interface TabItem {
  label: string;
  content: ReactNode;
}

interface TabsProps {
  items: TabItem[];
  defaultIndex?: number;
  activeIndex?: number; // ✅ new
  // eslint-disable-next-line no-unused-vars
  onChange?: (index: number) => void; // ✅ new
}

const Tabs: React.FC<TabsProps> = ({
  items,
  defaultIndex = 0,
  activeIndex,
  onChange,
}) => {
  // const [activeIndex, setActiveIndex] = useState(defaultIndex);

