                    View product
                  </Button>
                </div>
              </article>
            ))}
          </div>
        ) : (
          <div className="storefront-public__empty" role="status">
            <h3>No products are public right now</h3>
            <p>
              Draft and hidden products are not shown on public Storefronts.
            </p>
          </div>
        )}
      </section>
    </article>
  );
};

