  const hasReadinessBlockers = readinessResult.blockers.length > 0 ||
    readinessResult.isEvaluating;
  const isPublished = formData.status === 'PUBLISHED';
  const isMembership = formData.type === 'MEMBERSHIP';
  const canPreview = Boolean(formData.id);
  const previewDisabledReason = formData.id
    ? undefined
    : 'Save this Product before opening a private preview.';
  const publishHelpText = isPublished
    ? 'This Product is already published. Unpublish is not part of the current MVP lifecycle.'
    : isMembership
    ? 'Membership publishing is not available yet. Content metadata can be saved, but subscriptions, entitlements, and member access are unavailable.'
    : hasReadinessBlockers
    ? 'Publish will open Readiness until known blockers are resolved.'
    : 'Publish uses backend readiness validation after local checks pass.';

  useEffect(() => {
    setBackendReadinessIssues([]);
  }, [formData]);

  const backendReadinessDestinationByPath: Record<string, BuilderTab> = {
    name: 'basics',
    price: 'pricing',
    'details.sections': 'sections',
    'details.lessons': 'sections',
    'details.files': 'sections',
    'details.durationMinutes': 'consultation-details',
    'details.meetingMethod': 'consultation-details',
    'details.customLocation': 'consultation-details',
    'details.weeklyAvailability': 'consultation-details',
    status: 'readiness',
  };

  const isBackendReadinessError = (
    error: unknown,
  ): error is { message: string; errors: Record<string, string> } =>
    Boolean(
      error &&
      typeof error === 'object' &&
      'errors' in error &&
      typeof (error as { errors?: unknown }).errors === 'object',
    );

  const toBackendReadinessIssues = (
    errors: Record<string, string>,
  ): ProductReadinessIssue[] =>
    Object.entries(errors).map(([path, message]) => ({
      id: `backend-readiness-${path}`,
      severity: 'BLOCKER',
      title: path,
      description: message,
      destination: backendReadinessDestinationByPath[path] ?? 'readiness',
    }));

  const handleWorkspaceBack = async () => {
    try {
      await flushAutosave();
      navigate(appRoutes.products);
    } catch {
      const shouldLeave = window.confirm(
        'Latest Product changes could not be saved. Leave the workspace anyway?',
      );

      if (shouldLeave) {
        navigate(appRoutes.products);
      }
    }
  };

  const handlePreview = () => {
    if (!formData.id || !canPreview) {
      return;
    }

    navigate(appRoutes.productsPreview(formData.id));
  };

  const handlePublish = async () => {
    if (isPublished || isPublishing || isMembership) {
      return;
    }

    setPublishError(null);
    setBackendReadinessIssues([]);

    try {
      setIsPublishing(true);
      await flushAutosave();
    } catch {
      setActiveTab('readiness');
      setPublishError('Latest Product changes could not be saved. Resolve the save issue and try Publish again.');
      setIsPublishing(false);
      return;
    }

    if (hasReadinessBlockers) {
      setActiveTab('readiness');
      setPublishError(
        readinessResult.isEvaluating
          ? 'Readiness is still evaluating required Product data. Try again once it finishes loading.'
          : 'Resolve blockers before publishing this Product.',
      );
      setIsPublishing(false);
      return;
    }

    try {
      const payload = mapFormDataToProductPayload(
        {
          ...formData,
          status: 'PUBLISHED',
        },
        user,
      );
      const updatedProduct = await dispatch(updateProductDetails(payload)).unwrap();
      setField('status', updatedProduct.status ?? 'PUBLISHED');
    } catch (error) {
      if (isBackendReadinessError(error)) {
        setBackendReadinessIssues(toBackendReadinessIssues(error.errors));
        setPublishError(error.message);
      } else {
        setPublishError('Publish failed. Check the Product details and try again.');
      }
      setActiveTab('readiness');
    } finally {
      setIsPublishing(false);
    }
  };

  const renderReadinessPanel = () => (
    <ProductReadinessSection
      result={displayedReadinessResult}
      publishError={publishError}
      onNavigateToDestination={(destination) => setActiveTab(destination)}
    />
  );

  const renderActiveTabContent = () => {
    switch (activeTab) {
      case 'basics':
        return (
          <BasicInfo
            formData={formData}
            setField={setField}
            errors={errors}
            isEditMode={isEditMode}
          />
        );

      case 'pricing':
        return (
          <ProductPricingSection
            formData={formData}
            setField={setField}
            onMembershipRecurringPricingChange={
              handleMembershipRecurringPricingChange
            }
          />
        );

      case 'sections':
        return (
          <CreateProductSections
            sections={(formData as ProductWithSections).sections ?? []}
            productType={formData.type}
            productId={formData.id ?? ''}
            onSectionsChange={(sections) =>
              setField('sections', sections as SectionDraft[])
            }
          />
        );

      case 'consultation-details':
        return (
          <ConsultationDetailsSection
            formData={formData}
            errors={errors}
            setFormData={setFormData}
          />
        );

      case 'membership-content':
        return (
          <MembershipContentSection
            ownerId={productOwnerId}
            currentProductId={formData.id}
            nativeContentItems={membershipNativeContentItems}
            feedEntries={membershipFeedEntries}
            orderingMode={membershipOrderingMode}
            includedProductEntries={membershipIncludedProductEntries}
            productSummaries={productSummaries}
            includedProducts={includedProducts}
            isLoadingProducts={productsLoading || membershipLoading}
            productsError={productsError || membershipError}
            onAddNativeContentItem={handleCreateMembershipContent}
            onUpdateNativeContentItem={handleUpdateMembershipContent}
            onDeleteNativeContentItem={handleDeleteMembershipContent}
            onOrderingModeChange={handleMembershipOrderingModeChange}
            onAddIncludedProducts={handleAddIncludedProducts}
            onRemoveIncludedProduct={handleRemoveIncludedProduct}
            onMoveFeedEntry={handleMoveMembershipFeedEntry}
          />
        );

      case 'media':
        return (
          <ProductMediaSection
            productId={formData.id}
            productTitle={formData.name}
            thumbnailUrl={formData.imageUrl}
            galleryImages={formData.galleryImages as ProductGalleryImage[]}
            promoVideo={formData.promoVideo as ProductPromoVideo | null}
            onUploadThumbnail={handleUploadThumbnail}
            onRemoveThumbnail={handleRemoveThumbnail}
            onAddGalleryImage={handleAddGalleryImage}
            onRemoveGalleryImage={handleRemoveGalleryImage}
            onReorderGalleryImages={handleReorderGalleryImages}
            onUploadPromoVideo={handleUploadPromoVideo}
            onRemovePromoVideo={handleRemovePromoVideo}
          />
        );

      case 'readiness':
        return renderReadinessPanel();

      default:
        return null;
    }
  };

  const updateMembershipFeedForCurrentProduct = async (
    feed: MembershipFeedEntry[],
    orderingMode: MembershipOrderingMode = membershipOrderingMode,
  ) => {
    if (!formData.id) {
      throw new Error('Save this Membership before updating its content feed.');
    }

    await dispatch(
      updateMembershipFeed({
        productId: formData.id,
        payload: {
          orderingMode,
          feed: withFeedPositions(feed),
        },
      }),
    ).unwrap();
  };

  const handleMembershipRecurringPricingChange = (pricing: RecurringPricing) => {
    setField('price', pricing.amount);
    setField('pricingModel', 'RECURRING');
    setField('currency', pricing.currency);
    setField('billingInterval', pricing.interval);
  };

  const handleCreateMembershipContent = async (
    payload: MembershipContentCreateRequest,
  ) => {
    if (!formData.id) {
      throw new Error('Save this Membership before adding content.');
    }

    const result = await dispatch(
      createMembershipContent({ productId: formData.id, payload }),
    ).unwrap();

    const newEntry: MembershipFeedEntry = {
      entryId: `content:${result.content.id}`,
      kind: 'CONTENT',
      contentId: result.content.id,
      addedAt: result.content.createdAt,
    };
    const nextFeed =
      membershipOrderingMode === 'MANUAL'
        ? [newEntry, ...membershipFeedEntries]
        : [...membershipFeedEntries, newEntry];

    try {
      await updateMembershipFeedForCurrentProduct(nextFeed);
    } catch {
      try {
        await updateMembershipFeedForCurrentProduct(nextFeed);
      } catch {
        throw new Error(
          'Content was created, but it could not be attached to the Membership feed. Try again after the feed saves.',
        );
      }
    }
  };

  const handleUpdateMembershipContent = async (
    contentId: string,
    payload: MembershipContentUpdateRequest,
  ) => {
    if (!formData.id) {
      throw new Error('Save this Membership before updating content.');
    }

    await dispatch(
      updateMembershipContent({
        productId: formData.id,
        contentId,
        payload,
      }),
    ).unwrap();
  };

  const handleDeleteMembershipContent = async (contentId: string) => {
    if (!formData.id) {
      throw new Error('Save this Membership before deleting content.');
    }

    await dispatch(
      deleteMembershipContent({ productId: formData.id, contentId }),
    ).unwrap();
  };

  const handleMembershipOrderingModeChange = async (
    orderingMode: MembershipOrderingMode,
  ) => {
    const nextFeed =
      orderingMode === 'MANUAL' && membershipOrderingMode === 'NEWEST_FIRST'
        ? orderMembershipFeedEntries(membershipFeedEntries, 'NEWEST_FIRST')
        : membershipFeedEntries;

    await updateMembershipFeedForCurrentProduct(nextFeed, orderingMode);
  };

  const handleAddIncludedProducts = async (
    productIds: string[],
    addedAt: string,
  ) => {
    const existingProductIds = new Set(
      membershipIncludedProductEntries.map((entry) => entry.productId),
    );
    const newEntries = productIds
      .filter((productId) => !existingProductIds.has(productId))
      .map<MembershipFeedEntry>((productId) => ({
        entryId: `product:${productId}`,
        kind: 'PRODUCT',
        productId,
        addedAt,
      }));

    if (newEntries.length === 0) {
      return;
    }

    await updateMembershipFeedForCurrentProduct(
      membershipOrderingMode === 'MANUAL'
        ? [...newEntries, ...membershipFeedEntries]
        : [...membershipFeedEntries, ...newEntries],
    );
  };

  const handleRemoveIncludedProduct = async (productId?: string) => {
    if (!productId) {
      return;
    }

    await updateMembershipFeedForCurrentProduct(
      membershipFeedEntries.filter(
        (entry) => entry.kind !== 'PRODUCT' || entry.productId !== productId,
      ),
    );
  };

  const handleMoveMembershipFeedEntry = async (
    entryId: string,
    direction: 'UP' | 'DOWN',
  ) => {
    if (membershipOrderingMode !== 'MANUAL') {
      throw new Error('Switch to Manual order before moving feed entries.');
    }

    const currentIndex = membershipFeedEntries.findIndex(
      (entry) => entry.entryId === entryId,
    );
    const nextIndex = direction === 'UP' ? currentIndex - 1 : currentIndex + 1;

    if (
      currentIndex === -1 ||
      nextIndex < 0 ||
      nextIndex >= membershipFeedEntries.length
    ) {
      throw new Error('This feed entry cannot move any farther.');
    }

    const nextFeed = [...membershipFeedEntries];
    const currentEntry = nextFeed[currentIndex];

    nextFeed[currentIndex] = nextFeed[nextIndex];
    nextFeed[nextIndex] = currentEntry;

    await updateMembershipFeedForCurrentProduct(nextFeed);
  };

  const handleUploadThumbnail = async (file: File) => {
    if (!formData.id) {
      throw new Error('Save this Product before uploading a thumbnail.');
    }

    const result = await dispatch(
      addImageToProduct({ productId: formData.id, image: file }),
    ).unwrap();
    setField('imageUrl', result.imageUrl);

    return result.imageUrl;
  };

  const handleRemoveThumbnail = async () => {
    if (!formData.id) {
      throw new Error('Save this Product before removing a thumbnail.');
    }

    await dispatch(removeImageFromProduct({ productId: formData.id })).unwrap();
    setField('imageUrl', undefined);
  };

  const handleAddGalleryImage = async (file: File) => {
    if (!formData.id) {
      throw new Error('Save this Product before adding gallery images.');
    }

    const result = await dispatch(
      addProductGalleryImage({ productId: formData.id, image: file }),
    ).unwrap();
    setFormData((currentFormData) => ({
      ...currentFormData,
      galleryImages: [...(currentFormData.galleryImages ?? []), result.image]
        .slice()
        .sort((first, second) => first.position - second.position),
    }));

    return result.image;
  };

  const handleRemoveGalleryImage = async (imageId: string) => {
    if (!formData.id) {
      throw new Error('Save this Product before removing gallery images.');
    }

    await dispatch(
      removeProductGalleryImage({ productId: formData.id, imageId }),
    ).unwrap();
    setField(
      'galleryImages',
      (formData.galleryImages ?? [])
        .filter((image) => image.id !== imageId)
        .map((image, index) => ({ ...image, position: index + 1 })),
    );
  };

  const handleReorderGalleryImages = async (imageIds: string[]) => {
    if (!formData.id) {
      throw new Error('Save this Product before reordering gallery images.');
    }

    const result = await dispatch(
      reorderProductGalleryImages({ productId: formData.id, imageIds }),
    ).unwrap();
    setField('galleryImages', result.images);

    return result.images;
  };

  const handleUploadPromoVideo = async (file: File) => {
    if (!formData.id) {
      throw new Error('Save this Product before uploading a promo video.');
    }

    const result = await dispatch(
      addProductPromoVideo({ productId: formData.id, video: file }),
    ).unwrap();
    setField('promoVideo', result.promoVideo);

    return result.promoVideo;
  };

  const handleRemovePromoVideo = async () => {
    if (!formData.id) {
      throw new Error('Save this Product before removing a promo video.');
    }

    await dispatch(removeProductPromoVideo({ productId: formData.id })).unwrap();
    setField('promoVideo', null);
  };

  const workspaceNavigation =
    showRestOfForm && activeTab ? (
      <BuilderSidebar
        productType={formData.type}
        activeTab={activeTab}
        sections={sidebarSections}
        onChange={(tab) => setActiveTab(tab)}
        onSectionClick={handleSidebarSectionNavigation}
        onLessonClick={handleSidebarLessonNavigation}
      />
    ) : null;

  return (
    <ProductWorkspaceShell
      productType={formData.type}
      productTitle={formData.name}
      productStatus={formData.status}
      isEditMode={isEditMode}
      showWorkspace={showRestOfForm}
      saveStatus={saveStatus}
      hasPendingAutosave={hasPendingAutosave}
      canPublish={showRestOfForm && !isPublished && !isPublishing && !isMembership}
      publishDisabledReason={
        isPublished
          ? 'This Product is already published.'
          : isMembership
          ? 'Membership publishing is not available yet.'
          : undefined
      }
      isPublishing={isPublishing}
      canPreview={canPreview}
      previewDisabledReason={previewDisabledReason}
      publishHelpText={publishHelpText}
      onBack={handleWorkspaceBack}
      onPreview={handlePreview}
      onPublish={handlePublish}
      navigation={workspaceNavigation}
    >
      <div ref={container}>
        <form id="product-builder-form" ref={formRef} onSubmit={handleSubmit}>
        {!showRestOfForm && (
          <div
            className={clsx('product-create-hero', {
              'product-create-hero__collapsed': showRestOfForm,
              'product-create-hero__hidden': hasHeroCollapsed,
            })}
          >
            <CreateProductStepOne
              formData={formData}
              setField={setField}
              errors={errors}
              showRestOfForm={showRestOfForm}
              setShowRestOfForm={setShowRestOfForm}
              setShowLoadingRestOfForm={setShowLoadingRestOfForm}
              userId={productOwnerId ?? ''}
            />
          </div>
        )}

        {showLoadingRestOfForm && <p>Loading...</p>}

        {showRestOfForm && activeTab && (
          <div
            className={clsx('product-builder', {
              'product-builder__full': showRestOfForm,
            })}
          >
            <div className="product-create-section">
              <section
                id={`tab-panel-${activeTab}`}
                className="product-builder-panel"
                role="tabpanel"
                aria-labelledby={`builder-tab-${activeTab}`}
              >
                <div className="product-builder-panel__header">
                  <h2>{tabCopy[activeTab].title}</h2>
                  <p>{tabCopy[activeTab].description}</p>
                </div>
                <div className="product-builder-panel__body">
                  {renderActiveTabContent()}
                </div>
              </section>
            </div>
          </div>
        )}
        </form>
      </div>
    </ProductWorkspaceShell>
  );
};

export default ProductForm;

import { MeetingMethods } from 'core/enums';
import {
  ConsultationDayAvailability,
  ProductMinimised,
} from 'core/api/models';
import { BuilderTab } from '../builder-sidebar';
import { ProductDraft, RecurringPricing } from '../models';
import { MembershipContentItem } from '../membership-content/models';

export type ProductReadinessSeverity = 'BLOCKER' | 'WARNING';

export interface ProductReadinessIssue {
  id: string;
  severity: ProductReadinessSeverity;
  title: string;
  description: string;
  destination?: BuilderTab;
}

export interface ProductReadinessResult {
  blockers: ProductReadinessIssue[];
  warnings: ProductReadinessIssue[];
  isReadyToPublish: boolean;
  isEvaluating: boolean;
}

export interface ProductReadinessInput {
  formData: ProductDraft;
  recurringPricing?: RecurringPricing;
  membershipNativeContentItems?: readonly MembershipContentItem[];
  membershipIncludedProducts?: readonly ProductMinimised[];
  isMembershipLoading?: boolean;
}

const VALID_BILLING_INTERVALS: RecurringPricing['interval'][] = [
  'MONTH',
  'YEAR',
];

const createIssue = (
  id: string,
  severity: ProductReadinessSeverity,
  title: string,
  description: string,
  destination?: BuilderTab,
): ProductReadinessIssue => ({
  id,
  severity,
  title,
  description,
  destination,
});

const hasPositivePrice = (price: ProductDraft['price']) =>
  typeof price === 'number' && Number.isFinite(price) && price > 0;

const isOneTimePriceReady = (formData: ProductDraft) =>
  formData.price === 'free' || hasPositivePrice(formData.price);

const toMinutes = (value?: string) => {
  if (!value) {
    return NaN;
  }

  const [hours, minutes] = value.split(':').map(Number);

  return hours * 60 + minutes;
};

export const getConsultationDayValidation = (
  day: ConsultationDayAvailability,
): string | null => {
  if (!day.enabled) {
    return null;
  }

  if (day.windows.length === 0) {
    return 'Enabled days need at least one time range.';
  }

  const sorted = [...day.windows].sort(
    (a, b) => toMinutes(a.startTime) - toMinutes(b.startTime),
  );

  for (const window of sorted) {
    const start = toMinutes(window.startTime);
    const end = toMinutes(window.endTime);

    if (!Number.isFinite(start) || !Number.isFinite(end)) {
      return 'Start and end times are required.';
    }

    if (start >= end) {
      return 'Start time must be before end time.';
    }
  }

  for (let index = 1; index < sorted.length; index += 1) {
    const previous = sorted[index - 1];
    const current = sorted[index];

    if (toMinutes(current.startTime) < toMinutes(previous.endTime)) {
      return 'Time ranges cannot overlap.';
    }
  }

  return null;
};

const hasConfirmedDownloadFile = (formData: ProductDraft) =>
  (formData.sections ?? []).some((section) =>
    (section.files ?? []).some((file) => Boolean(file.id || file.url || file.fileName)),
  );

const hasCourseLesson = (formData: ProductDraft) =>
  (formData.sections ?? []).some((section) => (section.lessons ?? []).length > 0);

const hasAvailableConsultationWindow = (
  weeklyAvailability: ConsultationDayAvailability[] = [],
) =>
  weeklyAvailability.some(
    (day) =>
      day.enabled &&
      day.windows.some((window) => !getConsultationDayValidation({
        ...day,
        windows: [window],
      })),
  );

const hasInvalidConsultationAvailability = (
  weeklyAvailability: ConsultationDayAvailability[] = [],
) => weeklyAvailability.some((day) => Boolean(getConsultationDayValidation(day)));

const hasPublishedMembershipEntry = (
  nativeContentItems: readonly MembershipContentItem[] = [],
  includedProducts: readonly ProductMinimised[] = [],
) =>
  nativeContentItems.some((item) => item.status === 'PUBLISHED') ||
  includedProducts.some((product) => product.status === 'PUBLISHED');

const hasDraftMembershipContent = (
  nativeContentItems: readonly MembershipContentItem[] = [],
) => nativeContentItems.some((item) => item.status === 'DRAFT');

const hasBackendPendingPublishedBinaryContent = (
  nativeContentItems: readonly MembershipContentItem[] = [],
) =>
  nativeContentItems.some(
    (item) =>
      item.status === 'PUBLISHED' &&
      (item.type === 'VIDEO' || item.type === 'RESOURCE'),
  );

export const evaluateProductReadiness = ({
  formData,
  recurringPricing,
  membershipNativeContentItems = [],
  membershipIncludedProducts = [],
  isMembershipLoading = false,
}: ProductReadinessInput): ProductReadinessResult => {
  const blockers: ProductReadinessIssue[] = [];
  const warnings: ProductReadinessIssue[] = [];

  if (!formData.name?.trim()) {
    blockers.push(
      createIssue(
        'missing-name',
        'BLOCKER',
        'Add a Product name',
        'Customers need a clear Product name before this can be published.',
        'basics',
      ),
    );
  }

  if (formData.type === 'COURSE' || formData.type === 'DOWNLOAD') {
    if (!isOneTimePriceReady(formData)) {
      blockers.push(
        createIssue(
          'invalid-one-time-price',
          'BLOCKER',
          'Set valid pricing',
          'Choose Free or enter a positive one-time price.',
          'pricing',
        ),
      );
    }
  }

  if (formData.type === 'CONSULTATION' && !hasPositivePrice(formData.price)) {
    blockers.push(
      createIssue(
        'invalid-consultation-price',
        'BLOCKER',
        'Set a Consultation price',
        'Consultations require a positive one-time price in the MVP.',
        'pricing',
      ),
    );
  }

  if (formData.type === 'MEMBERSHIP') {
    const amount = recurringPricing?.amount ??
      (typeof formData.price === 'number' ? formData.price : 0);
    const interval = recurringPricing?.interval ?? formData.billingInterval;

    if (amount <= 0 || !VALID_BILLING_INTERVALS.includes(interval as RecurringPricing['interval'])) {
      blockers.push(
        createIssue(
          'invalid-recurring-price',
          'BLOCKER',
          'Set valid recurring pricing',
          'Memberships require a positive recurring price and monthly or yearly billing.',
          'pricing',
        ),
      );
    }
  }

  if (!formData.imageUrl) {
    warnings.push(
      createIssue(
        'missing-thumbnail',
        'WARNING',
        'Add a thumbnail',
        'Products with a thumbnail are easier to recognize across your storefront and Product pages.',
        'media',
      ),
    );
  }

  if (formData.type === 'COURSE') {
    if ((formData.sections ?? []).length === 0 || !hasCourseLesson(formData)) {
      blockers.push(
        createIssue(
          'course-needs-curriculum',
          'BLOCKER',
          'Add Course curriculum',
          'Courses need at least one section and one lesson before customers have something to learn.',
          'sections',
        ),
      );
    }
  }

  if (formData.type === 'DOWNLOAD' && !hasConfirmedDownloadFile(formData)) {
    blockers.push(
      createIssue(
        'download-needs-file',
        'BLOCKER',
        'Add at least one file',
        'Customers need something to receive from this Download.',
        'sections',
      ),
    );
  }

  if (formData.type === 'CONSULTATION') {
    const details = formData.consultationDetails;
    const weeklyAvailability = details?.weeklyAvailability ?? [];

    if (!details?.durationMinutes || details.durationMinutes <= 0) {
      blockers.push(
        createIssue(
          'consultation-duration',
          'BLOCKER',
          'Set a valid session duration',
          'Consultations need a positive session duration.',
          'consultation-details',
        ),
      );
    }

    if (!details?.meetingMethod) {
      blockers.push(
        createIssue(
          'consultation-meeting-method',
          'BLOCKER',
          'Choose a meeting method',
          'Customers need to know how the Consultation will happen.',
          'consultation-details',
        ),
      );
    }

    if (
      details?.meetingMethod === MeetingMethods.OTHER &&
      !details.customLocation?.trim()
    ) {
      blockers.push(
        createIssue(
          'consultation-custom-location',
          'BLOCKER',
          'Describe the custom meeting location',
          'Other meeting methods need customer-facing location or joining instructions.',
          'consultation-details',
        ),
      );
    }

    if (!hasAvailableConsultationWindow(weeklyAvailability)) {
      blockers.push(
        createIssue(
          'consultation-availability',
          'BLOCKER',
          'Add weekly availability',
          'Consultations need at least one valid weekly time range before customers can book.',
          'consultation-details',
        ),
      );
    }

    if (hasInvalidConsultationAvailability(weeklyAvailability)) {
      blockers.push(
        createIssue(
          'consultation-invalid-availability',
          'BLOCKER',
          'Fix availability ranges',
          'Availability ranges must have start and end times, start before end, and no overlaps.',
          'consultation-details',
        ),
      );
    }

    if ((details?.connectedCalendars ?? []).length === 0) {
      warnings.push(
        createIssue(
          'consultation-no-calendar',
          'WARNING',
          'Connect a calendar',
          'Calendar connection helps prevent future booking conflicts, but it is not required to publish.',
          'consultation-details',
        ),
      );
    }
  }

  if (formData.type === 'MEMBERSHIP' && !isMembershipLoading) {
    if (!hasPublishedMembershipEntry(
      membershipNativeContentItems,
      membershipIncludedProducts,
    )) {
      blockers.push(
        createIssue(
          'membership-needs-published-entry',
          'BLOCKER',
          'Add published Membership content',
          'Memberships need at least one published native item or published included Product.',
          'membership-content',
        ),
      );
    }

    if (hasDraftMembershipContent(membershipNativeContentItems)) {
      warnings.push(
        createIssue(
          'membership-has-draft-content',
          'WARNING',
          'Review Draft content',
          'Some Membership content is still Draft and will not be customer-ready.',
          'membership-content',
        ),
      );
    }

    if (hasBackendPendingPublishedBinaryContent(membershipNativeContentItems)) {
      warnings.push(
        createIssue(
          'membership-binary-media-backend-pending',
          'WARNING',
          'Confirm Membership media persistence',
          'Published Membership Video or Resource items currently rely on backend-pending durable media storage.',
          'membership-content',
        ),
      );
    }
  }

  return {
    blockers,
    warnings,
    isReadyToPublish: blockers.length === 0 && !isMembershipLoading,
    isEvaluating: formData.type === 'MEMBERSHIP' && isMembershipLoading,
  };
};

import React from 'react';

import { Button, StatusBadge } from '@shared/ui';
import { BuilderTab } from '../builder-sidebar';
import {
  ProductReadinessIssue,
  ProductReadinessResult,
} from './product-readiness.utils';

import './product-readiness-section.styles.scss';

interface ProductReadinessSectionProps {
  result: ProductReadinessResult;
  publishError?: string | null;
  // eslint-disable-next-line no-unused-vars
  onNavigateToDestination: (destination: BuilderTab) => void;
}

const destinationLabel: Partial<Record<BuilderTab, string>> = {
  basics: 'Basics',
  pricing: 'Pricing',
  sections: 'Content',
  'consultation-details': 'Availability',
  'membership-content': 'Content',
  media: 'Media',
};

const renderIssue = (
  issue: ProductReadinessIssue,
  // eslint-disable-next-line no-unused-vars
  onNavigateToDestination: (destination: BuilderTab) => void,
) => (
  <li className="product-readiness-issue" key={issue.id}>
    <div className="product-readiness-issue__content">
      <StatusBadge
        label={issue.severity === 'BLOCKER' ? 'Blocker' : 'Warning'}
        tone={issue.severity === 'BLOCKER' ? 'danger' : 'warning'}
        size="sm"
      />
      <div>
        <h4>{issue.title}</h4>
        <p>{issue.description}</p>
      </div>
    </div>
    {issue.destination && (
      <Button
        type="button"
        variant={issue.severity === 'BLOCKER' ? 'secondary' : 'tertiary'}
        size="sm"
        className="product-readiness-issue__action"
        aria-label={`Go to ${destinationLabel[issue.destination] ?? 'destination'} to resolve ${issue.title}`}
        onClick={() => onNavigateToDestination(issue.destination as BuilderTab)}
      >
        Go to {destinationLabel[issue.destination] ?? 'destination'}
      </Button>
    )}
  </li>
);

const ProductReadinessSection: React.FC<ProductReadinessSectionProps> = ({
  result,
  publishError,
  onNavigateToDestination,
}) => {
  const blockerCount = result.blockers.length;
  const warningCount = result.warnings.length;

  return (
    <div className="product-readiness" aria-live="polite">
      <section className="product-readiness__summary" aria-labelledby="readiness-summary-title">
        <StatusBadge
          label={
            result.isEvaluating
              ? 'Evaluating'
              : result.isReadyToPublish
                ? 'Ready to publish'
                : `${blockerCount} blocker${blockerCount === 1 ? '' : 's'} remaining`
          }
          tone={
            result.isEvaluating
              ? 'neutral'
              : result.isReadyToPublish
                ? 'success'
                : 'danger'
          }
        />
        <div>
          <h3 id="readiness-summary-title">
            {result.isEvaluating
              ? 'Checking readiness'
              : result.isReadyToPublish
                ? 'Ready to publish'
                : 'Needs attention before publishing'}
          </h3>
          <p>
            {result.isEvaluating
              ? 'Some required Product data is still loading. Readiness will update when it is available.'
              : result.isReadyToPublish
                ? 'Local readiness checks have passed. Backend validation will confirm this Product when publishing.'
                : 'Resolve blockers before publishing. Warnings are worth reviewing but do not block Publish.'}
          </p>
        </div>
      </section>

      {publishError && (
        <div className="product-readiness__error" role="alert">
          {publishError}
        </div>
      )}

      {result.blockers.length > 0 && (
        <section className="product-readiness__group" aria-labelledby="readiness-blockers-title">
          <div className="product-readiness__group-header">
            <h3 id="readiness-blockers-title">Blockers</h3>
            <span>{result.blockers.length}</span>
          </div>
          <ul>
            {result.blockers.map((issue) =>
              renderIssue(issue, onNavigateToDestination),
            )}
          </ul>
        </section>
      )}

      <section className="product-readiness__group" aria-labelledby="readiness-warnings-title">
        <div className="product-readiness__group-header">
          <h3 id="readiness-warnings-title">Warnings</h3>
          <span>{warningCount}</span>
        </div>
        {result.warnings.length > 0 ? (
          <ul>
            {result.warnings.map((issue) =>
              renderIssue(issue, onNavigateToDestination),
            )}
          </ul>
        ) : (
          <p className="product-readiness__empty">
            No warnings from the current frontend checks.
          </p>
        )}
      </section>
    </div>
  );
};

export default ProductReadinessSection;

