interface ConsultationDetailsProps {
  formData: ProductDraft;
  // eslint-disable-next-line no-unused-vars
  setFormData: (e: ProductDraft) => void;
  errors: FormErrors;
}

const DAY_LABELS: Record<ConsultationWeekday, string> = {
  MONDAY: 'Monday',
  TUESDAY: 'Tuesday',
  WEDNESDAY: 'Wednesday',
  THURSDAY: 'Thursday',
  FRIDAY: 'Friday',
  SATURDAY: 'Saturday',
  SUNDAY: 'Sunday',
};

const WEEKDAYS = Object.keys(DAY_LABELS) as ConsultationWeekday[];

const DEFAULT_WEEKLY_AVAILABILITY: ConsultationDayAvailability[] = WEEKDAYS.map(
  (day) => ({
    day,
    enabled: !['SATURDAY', 'SUNDAY'].includes(day),
    windows: !['SATURDAY', 'SUNDAY'].includes(day)
      ? [{ startTime: '09:00', endTime: '17:00' }]
      : [],
  }),
);

const TIME_OPTIONS: SelectOption[] = [30, 45, 50, 60, 75, 90, 120].map(
  (value) => ({
    value,
    label: value < 60 ? `${value} minutes` : `${value / 60} hour${value === 60 ? '' : 's'}`,
  }),
);

const MEETING_METHOD_OPTIONS: SelectOption[] = Object.entries(MEETING_METHODS)
  .map(([value, label]) => ({
    value,
    label,
  }));

const defaultPolicy = CANCELATION_POLICIES.find(
  (policy) => policy.id === CancelationPolicyId.Full24h,
);

const createDefaultConsultationDetails = (): ConsultationDetails => ({
  bufferAfterMinutes: 10,
  bufferBeforeMinutes: 10,
  cancellationPolicy: defaultPolicy?.id,
  confirmationMessage:
    'Thanks for booking. You will receive the session details after your booking is confirmed.',
  connectedCalendars: [],
  customLocation: '',
  durationMinutes: 50,
  maxSessionsPerDay: 8,
  meetingMethod: MeetingMethods.ZOOM,
  weeklyAvailability: DEFAULT_WEEKLY_AVAILABILITY,
});

const normalizeWeeklyAvailability = (
  value?: ConsultationDayAvailability[],
): ConsultationDayAvailability[] =>
  WEEKDAYS.map((day) => {
    const existing = value?.find((item) => item.day === day);
    const defaultDay = DEFAULT_WEEKLY_AVAILABILITY.find(
      (item) => item.day === day,
    ) ?? {
      day,
      enabled: false,
      windows: [],
    };

    if (existing) {
      return {
        day,
        enabled: existing.enabled,
        windows: existing.enabled && existing.windows.length === 0
          ? [{ startTime: '09:00', endTime: '17:00' }]
          : existing.windows,
      };
    }

    return defaultDay;
  });

const toMinutes = (value: string) => {
  const [hours, minutes] = value.split(':').map(Number);

  return hours * 60 + minutes;
};

const getDayValidation = (day: ConsultationDayAvailability): string | null => {
  if (!day.enabled) {
    return null;
  }

  if (day.windows.length === 0) {
    return `${DAY_LABELS[day.day]} needs at least one time range.`;
  }

  const sorted = [...day.windows].sort(
    (a, b) => toMinutes(a.startTime) - toMinutes(b.startTime),
  );

  for (const window of sorted) {
    if (!window.startTime || !window.endTime) {
      return 'Start and end times are required.';
    }

    if (toMinutes(window.startTime) >= toMinutes(window.endTime)) {
      return 'Start time must be before end time.';
    }
  }

  for (let index = 1; index < sorted.length; index += 1) {
    const previous = sorted[index - 1];
    const current = sorted[index];

    if (toMinutes(current.startTime) < toMinutes(previous.endTime)) {
      return 'Time ranges cannot overlap.';
    }
  }

  return null;
};

const ConsultationDetailsSection: React.FC<ConsultationDetailsProps> = ({
  formData,
  setFormData,
}) => {
  const navigate = useNavigate();

  useEffect(() => {
    if (formData.consultationDetails) {
      return;
    }

    setFormData({
      ...formData,
      consultationDetails: createDefaultConsultationDetails(),
    });
  }, [formData, setFormData]);

  const details = formData.consultationDetails ?? createDefaultConsultationDetails();
  const weeklyAvailability = useMemo(
    () => normalizeWeeklyAvailability(details.weeklyAvailability),
    [details.weeklyAvailability],
  );
  const connectedCalendars = details.connectedCalendars ?? [];
  const enabledDays = weeklyAvailability.filter((day) => day.enabled);
  const dayErrors = weeklyAvailability.reduce<Record<ConsultationWeekday, string | null>>(
    (acc, day) => ({
      ...acc,
      [day.day]: getDayValidation(day),
    }),
    {} as Record<ConsultationWeekday, string | null>,
  );
  const hasAvailabilityErrors = Object.values(dayErrors).some(Boolean);

  const updateDetails = (patch: Partial<ConsultationDetails>) => {
    setFormData({
      ...formData,
      consultationDetails: {
        ...details,
        ...patch,
      },
    });
  };

  const updateDay = (
    day: ConsultationWeekday,
    updater: (
      // eslint-disable-next-line no-unused-vars
      value: ConsultationDayAvailability,
    ) => ConsultationDayAvailability,
  ) => {
    updateDetails({
      weeklyAvailability: weeklyAvailability.map((item) =>
        item.day === day ? updater(item) : item,
      ),
    });
  };

  const updateWindow = (
    day: ConsultationWeekday,
    windowIndex: number,
    patch: Partial<ConsultationAvailabilityWindow>,
  ) => {
    updateDay(day, (item) => ({
      ...item,
      windows: item.windows.map((window, index) =>
        index === windowIndex ? { ...window, ...patch } : window,
      ),
    }));
  };

  const addRange = (day: ConsultationWeekday) => {
    updateDay(day, (item) => ({
      ...item,
      enabled: true,
      windows: [...item.windows, { startTime: '14:00', endTime: '17:00' }],
    }));
  };

  const removeRange = (day: ConsultationWeekday, windowIndex: number) => {
    updateDay(day, (item) => ({
      ...item,
      windows: item.windows.filter((_, index) => index !== windowIndex),
    }));
  };

  return (
    <div className="consultation-details">
      <section className="consultation-settings-section">
        <div className="consultation-settings-section__header">
          <div>
            <h3>Session</h3>
            <p>Define how this Consultation is delivered.</p>
          </div>
        </div>
        <div className="consultation-settings-grid">
          <Select
            options={TIME_OPTIONS}
            name="durationMinutes"
            label="Session duration"
            value={details.durationMinutes ?? 50}
            onChange={(event: React.ChangeEvent<HTMLSelectElement>) =>
              updateDetails({ durationMinutes: Number(event.target.value) })
            }
          />
          <Select
            options={MEETING_METHOD_OPTIONS}
            name="meetingMethod"
            label="Meeting method"
            value={details.meetingMethod ?? ''}
            onChange={(event: React.ChangeEvent<HTMLSelectElement>) =>
              updateDetails({ meetingMethod: event.target.value as MeetingMethods })
            }
          />
        </div>
        {details.meetingMethod === MeetingMethods.OTHER && (
          <Input
            label="Custom location or instructions"
            type="text"
            name="customLocation"
            value={details.customLocation ?? ''}
            onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
              updateDetails({ customLocation: event.target.value })
            }
          />
        )}
        {details.meetingMethod &&
          [MeetingMethods.ZOOM, MeetingMethods.GOOGLE_MEET].includes(
            details.meetingMethod as MeetingMethods,
          ) && (
          <p className="consultation-details__note">
            This records the intended delivery method. Automatic meeting-room
            creation remains integration-dependent.
          </p>
        )}
      </section>

      <section className="consultation-settings-section">
        <div className="consultation-settings-section__header">
          <div>
            <h3>Weekly availability</h3>
            <p>Choose when customers are allowed to book this Consultation.</p>
          </div>
          <StatusBadge
            label={
              enabledDays.length === 0
                ? 'No days available'
                : `${enabledDays.length} days available`
            }
            tone={
              enabledDays.length === 0 || hasAvailabilityErrors
                ? 'warning'
                : 'neutral'
            }
            size="sm"
          />
        </div>

        <div className="weekly-availability" aria-label="Weekly availability">
          {weeklyAvailability.map((day) => {
            const label = DAY_LABELS[day.day];
            const error = dayErrors[day.day];

            return (
              <div className="availability-day" key={day.day}>
                <div className="availability-day__summary">
                  <label className="availability-day__toggle">
                    <input
                      type="checkbox"
                      checked={day.enabled}
                      aria-describedby={
                        error ? `availability-${day.day}-error` : undefined
                      }
                      onChange={(event) =>
                        updateDay(day.day, (item) => ({
                          ...item,
                          enabled: event.target.checked,
                          windows: event.target.checked && item.windows.length === 0
                            ? [{ startTime: '09:00', endTime: '17:00' }]
                            : item.windows,
                        }))
                      }
                    />
                    <span>{label}</span>
                  </label>
                  {!day.enabled && (
                    <StatusBadge label="Unavailable" tone="neutral" size="sm" />
                  )}
                </div>

                {day.enabled && (
                  <div className="availability-day__ranges">
                    {day.windows.map((window, index) => (
                      <div className="availability-range" key={`${day.day}-${index}`}>
                        <Input
                          label={`${label} range ${index + 1} start`}
                          type="time"
                          name={`${day.day}-${index}-start`}
                          value={window.startTime}
                          error={index === 0 && error ? error : undefined}
                          onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
                            updateWindow(day.day, index, {
                              startTime: event.target.value,
                            })
                          }
                        />
                        <Input
                          label={`${label} range ${index + 1} end`}
                          type="time"
                          name={`${day.day}-${index}-end`}
                          value={window.endTime}
                          onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
                            updateWindow(day.day, index, {
                              endTime: event.target.value,
                            })
                          }
                        />
                        <Button
                          type="button"
                          variant="danger"
                          size="sm"
                          aria-label={`Remove ${label} range ${index + 1}`}
                          onClick={() => removeRange(day.day, index)}
                        >
                          Remove
                        </Button>
                      </div>
                    ))}
                    {error && (
                      <p
                        className="consultation-details__error"
                        id={`availability-${day.day}-error`}
                        role="alert"
                      >
                        {error}
                      </p>
                    )}
                    <Button
                      type="button"
                      variant="tertiary"
                      size="sm"
                      onClick={() => addRange(day.day)}
                    >
                      Add range
                    </Button>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </section>

      <section className="consultation-settings-section">
        <div className="consultation-settings-section__header">
          <div>
            <h3>Calendar</h3>
            <p>Account calendars are used later to protect against conflicts.</p>
          </div>
          <StatusBadge
            label={connectedCalendars.length > 0 ? 'Connected' : 'Not connected'}
            tone={connectedCalendars.length > 0 ? 'success' : 'warning'}
            size="sm"
          />
        </div>
        {connectedCalendars.length > 0 ? (
          <div className="calendar-status-list">
            {connectedCalendars.map((calendar, index) => (
              <div className="calendar-status" key={calendar.id ?? index}>
                <strong>{calendar.provider ?? 'Calendar'}</strong>
                <span>
                  {calendar.email ??
                    calendar.displayName ??
                    calendar.id ??
                    'Connected account calendar'}
                </span>
              </div>
            ))}
          </div>
        ) : (
          <div className="calendar-empty-state">
            <strong>No calendar connected</strong>
            <p>
              Connect a calendar in account settings to prevent future bookings
              from overlapping existing events. OAuth remains external to this
              Product builder.
            </p>
          </div>
        )}
        <Button
          type="button"
          variant="secondary"
          onClick={() => navigate('/app/settings?tab=calendar')}
        >
          Manage calendars
        </Button>
      </section>

      <section className="consultation-settings-section">
        <div className="consultation-settings-section__header">
          <div>
            <h3>Scheduling rules</h3>
            <p>Control spacing and daily load for this Consultation.</p>
          </div>
        </div>
        <div className="consultation-settings-grid consultation-settings-grid--three">
          <Input
            type="number"
            min={0}
            name="bufferBeforeMinutes"
            label="Buffer before (minutes)"
            value={details.bufferBeforeMinutes ?? 0}
            onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
              updateDetails({ bufferBeforeMinutes: Number(event.target.value) })
            }
          />
          <Input
            type="number"
            min={0}
            name="bufferAfterMinutes"
            label="Buffer after (minutes)"
            value={details.bufferAfterMinutes ?? 0}
            onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
              updateDetails({ bufferAfterMinutes: Number(event.target.value) })
            }
          />
          <Input
            type="number"
            min={1}
            name="maxSessionsPerDay"
            label="Maximum sessions per day"
            value={details.maxSessionsPerDay ?? 1}
            onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
              updateDetails({ maxSessionsPerDay: Number(event.target.value) })
            }
          />
        </div>
      </section>

      <section className="consultation-settings-section">
        <div className="consultation-settings-section__header">
          <div>
            <h3>Client communication</h3>
            <p>
              This message is shown after a customer successfully books this
              Consultation. Automated email delivery is not implemented here.
            </p>
          </div>
        </div>
        <Textarea
          label="Confirmation message"
          name="confirmationMessage"
          value={details.confirmationMessage ?? ''}
          onChange={(event: React.ChangeEvent<HTMLTextAreaElement>) =>
            updateDetails({ confirmationMessage: event.target.value })
          }
          block
        />
      </section>

      <section className="consultation-settings-section">
        <div className="consultation-settings-section__header">
          <div>
            <h3>Cancellation</h3>
            <p>Set the customer-facing policy for this Consultation.</p>
          </div>
        </div>
        <RadioGroup
          name="cancellationPolicy"
          value={details.cancellationPolicy ?? ''}
          onChange={(policyId) => updateDetails({ cancellationPolicy: policyId })}
          label="Cancellation policy"
          className="cancellation-group"
        >
          {CANCELATION_POLICIES.map((policy) => (
            <Radio
              key={policy.id}
              value={policy.id}
              label={policy.label}
              description={policy.notes}
            />
          ))}
        </RadioGroup>
      </section>
    </div>
  );
};

export default ConsultationDetailsSection;

import { MeetingMethods } from 'core/enums';
import {
  ConsultationDayAvailability,
  ProductMinimised,
} from 'core/api/models';
import { BuilderTab } from '../builder-sidebar';
import { ProductDraft, RecurringPricing } from '../models';
import { MembershipContentItem } from '../membership-content/models';

export type ProductReadinessSeverity = 'BLOCKER' | 'WARNING';

export interface ProductReadinessIssue {
  id: string;
  severity: ProductReadinessSeverity;
  title: string;
  description: string;
  destination?: BuilderTab;
}

export interface ProductReadinessResult {
  blockers: ProductReadinessIssue[];
  warnings: ProductReadinessIssue[];
  isReadyToPublish: boolean;
  isEvaluating: boolean;
}

export interface ProductReadinessInput {
  formData: ProductDraft;
  recurringPricing?: RecurringPricing;
  membershipNativeContentItems?: readonly MembershipContentItem[];
  membershipIncludedProducts?: readonly ProductMinimised[];
  isMembershipLoading?: boolean;
}

const VALID_BILLING_INTERVALS: RecurringPricing['interval'][] = [
  'MONTH',
  'YEAR',
];

const createIssue = (
  id: string,
  severity: ProductReadinessSeverity,
  title: string,
  description: string,
  destination?: BuilderTab,
): ProductReadinessIssue => ({
  id,
  severity,
  title,
  description,
  destination,
});

const hasPositivePrice = (price: ProductDraft['price']) =>
  typeof price === 'number' && Number.isFinite(price) && price > 0;

const isOneTimePriceReady = (formData: ProductDraft) =>
  formData.price === 'free' || hasPositivePrice(formData.price);

const toMinutes = (value?: string) => {
  if (!value) {
    return NaN;
  }

  const [hours, minutes] = value.split(':').map(Number);

  return hours * 60 + minutes;
};

export const getConsultationDayValidation = (
  day: ConsultationDayAvailability,
): string | null => {
  if (!day.enabled) {
    return null;
  }

  if (day.windows.length === 0) {
    return 'Enabled days need at least one time range.';
  }

  const sorted = [...day.windows].sort(
    (a, b) => toMinutes(a.startTime) - toMinutes(b.startTime),
  );

  for (const window of sorted) {
    const start = toMinutes(window.startTime);
    const end = toMinutes(window.endTime);

    if (!Number.isFinite(start) || !Number.isFinite(end)) {
      return 'Start and end times are required.';
    }

    if (start >= end) {
      return 'Start time must be before end time.';
    }
  }

  for (let index = 1; index < sorted.length; index += 1) {
    const previous = sorted[index - 1];
    const current = sorted[index];

    if (toMinutes(current.startTime) < toMinutes(previous.endTime)) {
      return 'Time ranges cannot overlap.';
    }
  }

  return null;
};

const hasConfirmedDownloadFile = (formData: ProductDraft) =>
  (formData.sections ?? []).some((section) =>
    (section.files ?? []).some((file) => Boolean(file.id || file.url || file.fileName)),
  );

const hasCourseLesson = (formData: ProductDraft) =>
  (formData.sections ?? []).some((section) => (section.lessons ?? []).length > 0);

const hasAvailableConsultationWindow = (
  weeklyAvailability: ConsultationDayAvailability[] = [],
) =>
  weeklyAvailability.some(
    (day) =>
      day.enabled &&
      day.windows.some((window) => !getConsultationDayValidation({
        ...day,
        windows: [window],
      })),
  );

const hasInvalidConsultationAvailability = (
  weeklyAvailability: ConsultationDayAvailability[] = [],
) => weeklyAvailability.some((day) => Boolean(getConsultationDayValidation(day)));

const hasPublishedMembershipEntry = (
  nativeContentItems: readonly MembershipContentItem[] = [],
  includedProducts: readonly ProductMinimised[] = [],
) =>
  nativeContentItems.some((item) => item.status === 'PUBLISHED') ||
  includedProducts.some((product) => product.status === 'PUBLISHED');

const hasDraftMembershipContent = (
  nativeContentItems: readonly MembershipContentItem[] = [],
) => nativeContentItems.some((item) => item.status === 'DRAFT');

const hasBackendPendingPublishedBinaryContent = (
  nativeContentItems: readonly MembershipContentItem[] = [],
) =>
  nativeContentItems.some(
    (item) =>
      item.status === 'PUBLISHED' &&
      (item.type === 'VIDEO' || item.type === 'RESOURCE'),
  );

export const evaluateProductReadiness = ({
  formData,
  recurringPricing,
  membershipNativeContentItems = [],
  membershipIncludedProducts = [],
  isMembershipLoading = false,
}: ProductReadinessInput): ProductReadinessResult => {
  const blockers: ProductReadinessIssue[] = [];
  const warnings: ProductReadinessIssue[] = [];

  if (!formData.name?.trim()) {
    blockers.push(
      createIssue(
        'missing-name',
        'BLOCKER',
        'Add a Product name',
        'Customers need a clear Product name before this can be published.',
        'basics',
      ),
    );
  }

  if (formData.type === 'COURSE' || formData.type === 'DOWNLOAD') {
    if (!isOneTimePriceReady(formData)) {
      blockers.push(
        createIssue(
          'invalid-one-time-price',
          'BLOCKER',
          'Set valid pricing',
          'Choose Free or enter a positive one-time price.',
          'pricing',
        ),
      );
    }
  }

  if (formData.type === 'CONSULTATION' && !hasPositivePrice(formData.price)) {
    blockers.push(
      createIssue(
        'invalid-consultation-price',
        'BLOCKER',
        'Set a Consultation price',
        'Consultations require a positive one-time price in the MVP.',
        'pricing',
      ),
    );
  }

  if (formData.type === 'MEMBERSHIP') {
    const amount = recurringPricing?.amount ??
      (typeof formData.price === 'number' ? formData.price : 0);
    const interval = recurringPricing?.interval ?? formData.billingInterval;

    if (amount <= 0 || !VALID_BILLING_INTERVALS.includes(interval as RecurringPricing['interval'])) {
      blockers.push(
        createIssue(
          'invalid-recurring-price',
          'BLOCKER',
          'Set valid recurring pricing',
          'Memberships require a positive recurring price and monthly or yearly billing.',
          'pricing',
        ),
      );
    }
  }

  if (!formData.imageUrl) {
    warnings.push(
      createIssue(
        'missing-thumbnail',
        'WARNING',
        'Add a thumbnail',
        'Products with a thumbnail are easier to recognize across your storefront and Product pages.',
        'media',
      ),
    );
  }

  if (formData.type === 'COURSE') {
    if ((formData.sections ?? []).length === 0 || !hasCourseLesson(formData)) {
      blockers.push(
        createIssue(
          'course-needs-curriculum',
          'BLOCKER',
          'Add Course curriculum',
          'Courses need at least one section and one lesson before customers have something to learn.',
          'sections',
        ),
      );
    }
  }

  if (formData.type === 'DOWNLOAD' && !hasConfirmedDownloadFile(formData)) {
    blockers.push(
      createIssue(
        'download-needs-file',
        'BLOCKER',
        'Add at least one file',
        'Customers need something to receive from this Download.',
        'sections',
      ),
    );
  }

  if (formData.type === 'CONSULTATION') {
    const details = formData.consultationDetails;
    const weeklyAvailability = details?.weeklyAvailability ?? [];

    if (!details?.durationMinutes || details.durationMinutes <= 0) {
      blockers.push(
        createIssue(
          'consultation-duration',
          'BLOCKER',
          'Set a valid session duration',
          'Consultations need a positive session duration.',
          'consultation-details',
        ),
      );
    }

    if (!details?.meetingMethod) {
      blockers.push(
        createIssue(
          'consultation-meeting-method',
          'BLOCKER',
          'Choose a meeting method',
          'Customers need to know how the Consultation will happen.',
          'consultation-details',
        ),
      );
    }

    if (
      details?.meetingMethod === MeetingMethods.OTHER &&
      !details.customLocation?.trim()
    ) {
      blockers.push(
        createIssue(
          'consultation-custom-location',
          'BLOCKER',
          'Describe the custom meeting location',
          'Other meeting methods need customer-facing location or joining instructions.',
          'consultation-details',
        ),
      );
    }

    if (!hasAvailableConsultationWindow(weeklyAvailability)) {
      blockers.push(
        createIssue(
          'consultation-availability',
          'BLOCKER',
          'Add weekly availability',
          'Consultations need at least one valid weekly time range before customers can book.',
          'consultation-details',
        ),
      );
    }

    if (hasInvalidConsultationAvailability(weeklyAvailability)) {
      blockers.push(
        createIssue(
          'consultation-invalid-availability',
          'BLOCKER',
          'Fix availability ranges',
          'Availability ranges must have start and end times, start before end, and no overlaps.',
          'consultation-details',
        ),
      );
    }

    if ((details?.connectedCalendars ?? []).length === 0) {
      warnings.push(
        createIssue(
          'consultation-no-calendar',
          'WARNING',
          'Connect a calendar',
          'Calendar connection helps prevent future booking conflicts, but it is not required to publish.',
          'consultation-details',
        ),
      );
    }
  }

  if (formData.type === 'MEMBERSHIP' && !isMembershipLoading) {
    if (!hasPublishedMembershipEntry(
      membershipNativeContentItems,
      membershipIncludedProducts,
    )) {
      blockers.push(
        createIssue(
          'membership-needs-published-entry',
          'BLOCKER',
          'Add published Membership content',
          'Memberships need at least one published native item or published included Product.',
          'membership-content',
        ),
      );
    }

    if (hasDraftMembershipContent(membershipNativeContentItems)) {
      warnings.push(
        createIssue(
          'membership-has-draft-content',
          'WARNING',
          'Review Draft content',
          'Some Membership content is still Draft and will not be customer-ready.',
          'membership-content',
        ),
      );
    }

    if (hasBackendPendingPublishedBinaryContent(membershipNativeContentItems)) {
      warnings.push(
        createIssue(
          'membership-binary-media-backend-pending',
          'WARNING',
          'Confirm Membership media persistence',
          'Published Membership Video or Resource items currently rely on backend-pending durable media storage.',
          'membership-content',
        ),
      );
    }
  }

  return {
    blockers,
    warnings,
    isReadyToPublish: blockers.length === 0 && !isMembershipLoading,
    isEvaluating: formData.type === 'MEMBERSHIP' && isMembershipLoading,
  };
};

